/* Shared celestial artwork replaces the older CSS-drawn back. */
.card-back {
  background: var(--surface);
  border-color: rgba(221,187,120,.34);
}
.card-back::before,
.card-back .cb-coin { display: none; }

/* NC STYLES: SPREADS */
.spread-grid {
  display: grid;
  grid-template-columns: 1.5rem repeat(7, minmax(0, 1fr)) 1.5rem;
  gap: .45rem .35rem;
  align-items: center;
  width: 100%;
  max-width: var(--reading-max-w);
  margin: 0 auto;
}
.spread-col-label {
  text-align: center; font-size: 1.5rem;
  color: var(--text-muted); padding-top: .4rem; line-height: 1;
}
.planet-row-label {
  display: grid;
  place-items: center;
  min-width: 0;
  color: var(--text-muted);
  font-size: 1.2rem;
  line-height: 1;
}
.planet-row-label[data-planet="Mars"],
.planet-col-label[data-planet="Mars"] { font-size: 1.05rem; }
.planet-row-label[data-planet="Venus"],
.planet-col-label[data-planet="Venus"] { font-size: 1.05rem; }
.spread-label-corner { min-width: 0; }
.crown-row {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 1.5rem repeat(7, minmax(0, 1fr)) 1.5rem;
  gap: .45rem .35rem;
  margin-top: 1.25rem;
}
.sl-joker-row {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 1.5rem repeat(7, minmax(0, 1fr)) 1.5rem;
  gap: .45rem .35rem;
  align-items: center;
}
.sl-joker-row .spread-card { grid-column: 2; width: 100%; cursor: pointer; }
.sl-joker-row > .sl-solar-value { grid-column: 2; }
.crown-side { grid-column: span 2; min-width: 0; }
.planet-col-label {
  font-size: 1.32rem;
  padding-top: .12rem;
}

.sl-seat { min-width: 0; display: flex; flex-direction: column; align-items: center; }
.sl-seat .spread-card { order: 0; width: 100%; }
.spread-grid button.spread-card { appearance: none; display: block; padding: 0; font: inherit; text-align: inherit; }
.sl-ghost-row { order: 1; display: flex; justify-content: center; gap: .12rem; margin-top: .22rem; width: 100%; max-width: 100%; }
.sl-ghost {
  display: none;
  flex: 1 1 0;
  min-inline-size: 0;
  max-inline-size: calc((100% - .12rem) / 2);
  block-size: var(--mini-card-h);
  padding: 0 .08rem;
  align-items: center;
  justify-content: center;
  font-family: var(--serif);
  font-size: clamp(.44rem, 1.35vw, var(--mini-card-font));
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1;
  border: 1px solid rgba(75,57,31,.18);
  border-radius: var(--card-radius);
  background: rgba(253,250,245,.88);
  white-space: nowrap; user-select: none; pointer-events: none;
}
.spread-grid.sl-ghosts .sl-ghost-d,
.spread-grid.sl-ghosts-by .sl-ghost-b { display: inline-flex; }
.sl-solar-value {
  display: none;
  flex: 1 1 0;
  min-inline-size: 0;
  block-size: var(--mini-card-h);
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(75,57,31,.18);
  border-radius: var(--card-radius);
  background: rgba(253,250,245,.88);
  color: var(--card-dark);
  font-family: var(--serif);
  font-size: clamp(.44rem, 1.35vw, var(--mini-card-font));
  font-weight: 700;
  line-height: 1;
}
.spread-grid.sl-solar-values .sl-solar-value { display: inline-flex; }
.spread-grid.sl-solar-values .sl-ghost { display: none; }
.spread-grid.sl-solar-card-values .sl-card-solar-value { display: block; }
.spread-grid.sl-solar-card-values .spread-card:not(.joker) .cc-solar-suit { display: block; }
.spread-grid.sl-solar-card-values .spread-card:not(.joker) .card-pips,
.spread-grid.sl-solar-card-values .spread-card:not(.joker) .court-art,
.spread-grid.sl-solar-card-values .spread-card:not(.joker) .court-pip { display: none !important; }
.spread-grid.sl-solar-card-values .spread-card.joker .court-art { display: none !important; }
.spread-grid.sl-solar-card-values .sl-solar-value,
.spread-grid.sl-solar-card-values .sl-ghost { display: none !important; }
.sl-card-solar-value {
  position: absolute; inset: 25% 0; align-content: center; text-align: center;
  font-family: var(--serif); font-size: 44cqw; line-height: 1; font-weight: 500;
  color: var(--card-dark); pointer-events: none;
}
.sl-ghost-self { visibility: hidden; }
.sl-card-binary { display: none; position: absolute; inset: 25% 0; align-content: center; text-align: center; font-family: monospace; font-size: 17cqw; line-height: 1; color: var(--card-dark); pointer-events: none; }
.spread-grid.sl-binary .sl-card-binary { display: block; }
.spread-grid.sl-binary .spread-card[data-binary-bit="1"] {
  background: color-mix(in srgb, var(--card-paper) 80%, var(--card-dark));
}
.sl-card-binary-bit { display: none; position: absolute; top: 2.5%; left: 50%; transform: translateX(-50%); text-align: center; font-family: monospace; font-size: 24cqw; line-height: 1; color: var(--card-dark); pointer-events: none; }
.spread-grid.sl-binary .sl-card-binary-bit { display: block; }
.sl-card-binary-decimal { display: none; position: absolute; bottom: 2.5%; left: 4%; text-align: left; font-family: monospace; font-size: 20cqw; line-height: 1; color: var(--card-dark); pointer-events: none; }
.spread-grid.sl-binary .sl-card-binary-decimal { display: block; }
.sl-card-binary-reverse { display: none; position: absolute; bottom: 2.5%; right: 4%; text-align: right; font-family: monospace; font-size: 20cqw; line-height: 1; color: var(--card-dark); pointer-events: none; }
.spread-grid.sl-binary .sl-card-binary-reverse { display: block; }
.spread-grid.sl-binary .spread-card:not(.joker) .card-br { display: none; }
.spread-grid.sl-binary .cc-solar-suit { display: block; }
.spread-grid.sl-binary .card-pips,
.spread-grid.sl-binary .court-art,
.spread-grid.sl-binary .court-pip,
.spread-grid.sl-binary .sl-card-solar-value,
.spread-grid.sl-binary .sl-solar-value,
.spread-grid.sl-binary .sl-ghost { display: none !important; }
.sl-ghost.hearts, .sl-ghost.diamonds { color: var(--red); }
.sl-ghost.clubs  { color: var(--green); }
.sl-ghost.spades { color: var(--navy); }

.court-only { display: none; }
body.pips-only .spread-card:not(.joker) .court-art,
body.pips-only .spread-card:not(.joker) .court-pip { display: none; }
body.pips-only .spread-card:not(.joker) .court-only { display: block; }

.shell-hero {
  min-height: calc(100vh - 128px);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 2rem 1rem; text-align: center;
}
.shell-hero .shell-eyebrow {
  font-family: var(--mono); font-size: var(--text-xs);
  letter-spacing: .18em; text-transform: uppercase;
  color: var(--gold-ink); opacity: .7; margin-bottom: 1rem;
}
.shell-hero h1 {
  font-family: var(--serif); font-size: clamp(2rem, 5vw, 3rem);
  color: var(--text); margin-bottom: 1rem;
}
.shell-hero p {
  color: var(--secondary); font-size: var(--text-md);
  max-width: 42ch; line-height: 1.7;
}

@view-transition { navigation: auto; }
::view-transition-old(root), ::view-transition-new(root) { animation-duration: .42s; }

.pg-veil {
  position: fixed; inset: 0; z-index: 9000; pointer-events: none;
  background: radial-gradient(125% 85% at 50% -8%, #202020 0%, #151515 46%, #101010 100%);
  opacity: 0; transition: opacity .34s ease;
}
.pg-veil.show { opacity: 1; }

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*), ::view-transition-old(*), ::view-transition-new(*) { animation: none !important; }
  .pg-veil { transition: none; }
}
.finder,
.quadrations {
  --ctl-pill-pad-y: .46rem;
  --ctl-pill-pad-x: 1rem;
  --ctl-pill-font: .64rem;
  --ctl-pill-track: .08em;
  --ctl-round-size: var(--tap-target);
  --ctl-round-font: 1rem;
  --finder-tool-size: var(--tap-target);
  --ctl-date-font: .95rem;
  --ctl-date-pad-y: .35rem;
  --ctl-date-pad-x: .9rem;
  --ctl-date-minw: 11rem;
}

.finder.page-section.section-open > .section-bodywrap { margin-top: 0; }

.quadrations-inline {
  border-top: 0;
}
.quadrations-inline[hidden] { display: none; }
.quadrations-inline .quadrations { margin: 0; }
.quadrations.page-section.section-open > .section-bodywrap { margin-top: 0; }
.quadrations.page-section.section-open .section-bodymin { padding-top: 0; }
.spreads-top {
  display: flex; flex-direction: column;
  align-items: center; gap: .45rem; margin-bottom: .35rem;
  position: relative;
}
@media (min-width: 900px) {
  .spreads-top {
    width: min(100%, var(--control-rail-w));
    margin-inline: auto;
  }
}
.spread-layout { display: flex; gap: 1.25rem; align-items: flex-start; justify-content: center; }
.spread-stack { position: relative; display: block; width: 100%; }
.spread-wrap {
  overflow-x: auto;
  padding: 1.25rem 0 1.5rem;
  -webkit-overflow-scrolling: touch;
  flex: 1;
  min-width: 0;
  display: flex;
  justify-content: flex-start;
}

.age-controls-wrap {
  display: grid;
  grid-template-columns: repeat(2, auto);
  justify-content: center;
  align-items: start;
  gap: var(--space-5);
  width: 100%;
  max-width: var(--control-rail-w);
  margin-inline: auto;
  margin-bottom: var(--space-2);
  padding: var(--space-2) 0;
  border: 0;
  background: transparent;
}
.age-controls-wrap[hidden] { display: none; }
.q-control-group {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.q-control-group legend {
  margin: 0 auto var(--space-1);
  padding: 0;
  color: var(--muted);
  font: 600 .58rem/1.2 var(--sans);
  letter-spacing: .12em;
  text-transform: uppercase;
}
.q-control-group > .age-controls { justify-content: center; }
.q-size-value { position: relative; display: block; }
.q-size-stepper .age-input { width: 3.4rem; padding-right: 1rem; }
.q-size-unit {
  position: absolute;
  top: 50%;
  right: .4rem;
  translate: 0 -50%;
  color: var(--muted);
  font: 500 .68rem/1 var(--sans);
  pointer-events: none;
}
.age-controls-wrap .age-btn:disabled { opacity: .4; cursor: default; }
.age-controls { display: flex; align-items: center; gap: .35rem; }
.age-btn {
  width: 1.8rem; height: 1.8rem; border-radius: 50%;
  background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.12);
  font-size: 1.1rem; color: rgba(255,255,255,.7);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--ease); cursor: pointer;
}
.age-btn:hover { background: rgba(255,255,255,.16); color: #fff; }
.age-input {
  width: 2.4rem; height: 1.8rem;
  border: 1px solid rgba(255,255,255,.12); border-radius: var(--r-sm);
  background: rgba(255,255,255,.08); color: rgba(255,255,255,.9);
  font-family: var(--sans); font-size: .9rem; font-weight: 500;
  text-align: center; padding: 0 .4rem;
  -moz-appearance: textfield;
  cursor: text;
}
.age-input::-webkit-inner-spin-button,
.age-input::-webkit-outer-spin-button { -webkit-appearance: none; }
.age-input:focus { outline: none; border-color: var(--gold); }
.q-disp-toggle {
  display: grid;
  grid-template-columns: 1rem minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-1);
  width: 100%;
  min-height: 1.6rem;
  padding: .15rem 0;
  border: 0;
  border-radius: var(--r-sm);
  background: transparent;
  color: rgba(255,255,255,.62);
  font: 500 .68rem/1.2 var(--sans);
  text-align: left;
  cursor: pointer;
  transition: color var(--ease);
}
.q-disp-toggle:hover { color: var(--gold-ink); }
.q-disp-toggle.on { color: var(--gold); }
.q-disp-toggle:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.q-toggle-icon { display: grid; place-items: center; font: 400 .9rem/1 var(--serif); }
.q-toggle-icon svg { width: .9rem; height: .9rem; fill: none; stroke: currentColor; stroke-width: 1.65; stroke-linecap: round; stroke-linejoin: round; }
.q-switch-track {
  position: relative;
  width: 1.85rem;
  height: 1rem;
  border: 1px solid var(--rule-strong);
  border-radius: 999px;
  background: rgba(255,255,255,.06);
  transition: background var(--ease), border-color var(--ease);
}
.q-switch-track::after {
  content: '';
  position: absolute;
  top: .13rem;
  left: .14rem;
  width: .62rem;
  height: .62rem;
  border-radius: 50%;
  background: var(--muted);
  transition: transform var(--ease), background var(--ease);
}
.q-disp-toggle.on .q-switch-track { border-color: var(--gold); background: rgba(199,154,84,.2); }
.q-disp-toggle.on .q-switch-track::after { transform: translateX(.82rem); background: var(--gold); }
.q-display-toggles { display: grid; gap: var(--space-1); }
.q-controls-menu .q-display-toggles { grid-template-columns: 1fr; justify-items: center; gap: var(--space-1); }
.q-controls-menu .q-disp-toggle {
  grid-template-columns: 1.85rem 1rem minmax(0, 1fr);
  justify-self: stretch;
  width: 100%;
}
.q-controls-menu .q-disp-toggle .q-switch-track { grid-column: 1; grid-row: 1; justify-self: start; }
.q-controls-menu .q-disp-toggle .q-toggle-icon { grid-column: 2; grid-row: 1; }
.q-controls-menu .q-disp-toggle > span:nth-child(2) { grid-column: 3; grid-row: 1; }
.q-size-control {
  display: flex;
  align-items: center;
  justify-content: center;
  inline-size: 4.8rem;
  min-block-size: 1.35rem;
}
.q-size-control input {
  width: 100%;
  accent-color: var(--gold);
  cursor: pointer;
}
.q-size-control input:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

.age-controls-wrap { min-height: var(--tap-target); }
/* NC STYLES: MENU */
.q-controls-menu {
  position: static;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr);
  align-items: start;
  gap: var(--space-3);
  width: min(24rem, calc(100vw - 1.5rem));
  max-width: none;
  max-height: none;
  overflow: visible;
  margin: 0 auto var(--space-3);
  padding: var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  background: rgba(255,255,255,.025);
  box-shadow: none;
}
.q-controls-menu[hidden] { display: none; }
.q-controls-menu { grid-template-columns: minmax(0, 1fr); width: min(23rem, calc(100vw - 1.5rem)); }
.q-mode-options { display: flex; flex-wrap: wrap; gap: var(--space-1); }
.q-mode-options button { flex: 1 1 auto; padding: var(--space-2); border: 1px solid var(--border); border-radius: var(--r-md); background: var(--surface); color: var(--text); font: inherit; cursor: pointer; }
.q-mode-options button[aria-pressed="true"] { background: var(--gold-light); color: var(--gold-ink); border-color: var(--gold-ink); }
.q-mode-options button:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.q-mode-detail { margin-top: var(--space-2); font-size: .85rem; }
.q-mode-detail > .q-mode-options { margin-top: var(--space-1); }
.q-mode-detail[hidden] { display: none; }
.q-controls-menu .q-control-group { width: 100%; }
.q-controls-menu .q-control-group legend { margin-bottom: var(--space-2); }
.q-controls-menu .q-display-toggles { justify-items: stretch; }
.q-controls-menu .q-size-stepper .age-controls { gap: var(--space-1); }
.q-size-stepper { display: grid; gap: var(--space-2); }
.q-size-slider-row {
  display: grid;
  grid-template-columns: auto minmax(5rem, 1fr) auto;
  align-items: center;
  gap: var(--space-2);
  color: var(--muted);
  font: 500 .56rem/1 var(--sans);
}
.q-size-slider-row input {
  width: 100%;
  margin: 0;
  accent-color: var(--gold);
  cursor: pointer;
}
.q-size-slider-row input:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
.q-mode-current {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  padding: .5rem;
  white-space: pre-line;
  text-align: center;
  line-height: 1.18;
  font-family: var(--sans); font-size: .62rem; font-weight: 600;
  letter-spacing: .14em; text-transform: uppercase; color: var(--gold-ink);
}
.crown-controls { align-self: start; aspect-ratio: 3 / 2; }
.q-chart-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: var(--space-2);
  width: min(100%, var(--reading-max-w));
  margin-inline: auto;
  padding: .35rem 0;
}
.q-chart-age {
  grid-column: 2;
  gap: .15rem;
  padding: 0;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.03)),
    rgba(17,12,33,.38);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 8px 24px rgba(0,0,0,.16);
}
.q-chart-age .age-btn,
.q-chart-age .age-input { min-height: var(--tap-target); height: var(--tap-target); }
.q-chart-age .age-btn {
  width: var(--tap-target);
  border: 0;
  background: transparent;
  color: var(--secondary);
}
.q-chart-age .age-btn:hover { background: var(--gold-light); color: var(--gold-ink); }
.q-chart-age .age-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: 1px; }
.q-chart-age .age-input {
  width: 3.2rem;
  border: 0;
  border-inline: 1px solid var(--rule);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  font-size: .84rem;
  font-weight: 600;
}
.q-menu-toggle {
  grid-column: 3;
  justify-self: end;
  display: inline-grid;
  align-items: center;
  justify-content: center;
  width: var(--tap-target);
  min-height: var(--tap-target);
  height: var(--tap-target);
  padding: 0;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: var(--r-md);
  background:
    linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.03)),
    rgba(17,12,33,.38);
  color: var(--secondary);
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 8px 24px rgba(0,0,0,.16);
  transition: border-color var(--ease), color var(--ease), background var(--ease);
}
.q-menu-toggle.on { border-color: var(--gold-ink); color: var(--gold-ink); background: var(--gold-light); }
@media (hover: hover) and (pointer: fine) {
  .q-menu-toggle:hover { border-color: var(--gold-ink); color: var(--gold-ink); background: var(--gold-light); }
}
.q-menu-toggle:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.q-menu-toggle svg {
  width: .9rem;
  height: .9rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
}

/* Keep the same base chart width while giving zoomed content the full viewport
   scroll range needed to stay centered on narrow screens. */
