  width: calc(min(calc(100% - 3rem), 560px) * var(--quad-scale, 1));
  max-width: none;
}
.quadrations .crown-row { margin-top: 0; }
@media (max-width: 700px) {
  .spread-layout { flex-direction: column; align-items: center; }
