  .q-chart-toolbar .q-chart-age .age-input {
    min-height: 2.25rem;
    height: 2.25rem;
  }
  .q-chart-toolbar .q-chart-age .age-btn { width: 2.25rem; font-size: .9rem; }
  .q-chart-toolbar .q-chart-age .age-input { width: 2.5rem; font-size: .78rem; }
  .q-chart-toolbar .q-menu-toggle {
    min-height: 2.25rem;
    width: 2.25rem;
    height: 2.25rem;
    padding: 0;
  }
  .q-chart-toolbar .q-menu-toggle svg { width: .78rem; height: .78rem; }
  .age-controls-wrap { grid-template-columns: 1fr; }
  .age-controls-wrap { padding: var(--space-2); }
  .age-controls-wrap .age-controls { gap: var(--space-1); }
