.spread-card:hover { box-shadow: var(--sh-md); transform: translateY(-2px); border-color: var(--rule-strong); }

.spread-card.finder-pick {
  border-color: var(--gold);
  box-shadow:
    0 0 0 3px var(--gold),
    0 0 0 6px rgba(205,168,95,.22),
    0 0 16px 3px rgba(205,168,95,.55),
    0 8px 22px rgba(181,134,74,.42);
  z-index: 4;
  animation: finderGlow 2.6s ease-in-out infinite;
}
.spread-card.finder-pick::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(65deg, transparent 34%, rgba(255,252,242,.4) 47%, rgba(255,255,255,.85) 50%, rgba(255,252,242,.4) 53%, transparent 66%);
  transform: translateX(130%);
  animation: finderShine 5.5s linear infinite;
  pointer-events: none;
  z-index: 3;
}
.spread-card.finder-pick:hover {
  box-shadow:
    0 0 0 3px var(--gold),
    0 0 0 7px rgba(205,168,95,.28),
    0 0 20px 4px rgba(205,168,95,.68),
    0 8px 22px rgba(181,134,74,.46);
}

@keyframes finderGlow {
  0%, 100% {
    box-shadow:
      0 0 0 3px var(--gold),
      0 0 0 5px rgba(205,168,95,.15),
      0 0 13px 2px rgba(205,168,95,.40),
      0 8px 22px rgba(181,134,74,.40);
  }
  50% {
    box-shadow:
      0 0 0 3px var(--gold),
      0 0 0 8px rgba(205,168,95,.30),
      0 0 22px 5px rgba(205,168,95,.72),
      0 9px 24px rgba(181,134,74,.46);
  }
}

@keyframes finderShine {
  0%   { transform: translateX(130%); }
  16%  { transform: translateX(-130%); }
  100% { transform: translateX(-130%); }
}

@media (prefers-reduced-motion: reduce) {
  .spread-card.finder-pick { animation: none; }
  .spread-card.finder-pick::after { animation: none; opacity: 0; }
}

.spread-card.finder-pick-partner {
  border-color: #b7add6;
  box-shadow: 0 0 0 2px #b7add6, 0 0 12px 2px rgba(183,173,214,.5);
  z-index: 3;
}
.spread-card.finder-pick-partner:hover { box-shadow: 0 0 0 2px #b7add6, 0 0 16px 3px rgba(183,173,214,.65); }
.spread-card.finder-pick.finder-pick-partner {
  border-color: var(--gold);
  box-shadow: 0 0 0 2px var(--gold), 0 0 0 5px #b7add6, 0 0 18px 3px rgba(199,154,84,.7);
}

.ls-lifespread .spread-card.ls-pick:not(.finder-pick) {
  border-color: var(--ls-color, var(--gold));
  z-index: 3;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ls-color, var(--gold)) 75%, transparent), 0 0 12px 2px color-mix(in srgb, var(--ls-color, var(--gold)) 45%, transparent);
  animation: none;
}
.ls-lifespread .spread-card.ls-pick:not(.finder-pick)::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(65deg, transparent 36%, rgba(240,224,190,.24) 47%, rgba(255,246,224,.52) 50%, rgba(240,224,190,.24) 53%, transparent 64%);
  transform: translateX(130%);
  animation: finderShine 6.5s linear infinite;
  animation-delay: calc(var(--ls-i, 0) * .4s);
  pointer-events: none;
  z-index: 3;
}

@keyframes lsIdleGlow {
  0%, 100% { box-shadow: 0 0 0 2px rgba(205,168,95,.24), 0 0 10px 1px rgba(205,168,95,.22), 0 7px 15px rgba(0,0,0,.24); }
  50%      { box-shadow: 0 0 0 3px rgba(205,168,95,.38), 0 0 17px 3px rgba(205,168,95,.40), 0 8px 17px rgba(0,0,0,.26); }
}

@media (prefers-reduced-motion: reduce) {
  .ls-lifespread .spread-card.ls-pick:not(.finder-pick) {
    animation: none;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--ls-color, var(--gold)) 75%, transparent), 0 0 9px 1px color-mix(in srgb, var(--ls-color, var(--gold)) 35%, transparent), 0 7px 13px rgba(0,0,0,.26);
