}
/* Keep restore close to the selected card without shifting the card layout. */
.finder-results > .finder-date-reset {
  position: absolute; right: calc(50% + var(--finder-card-w) / 2 + 1.25rem);
  top: 50%; transform: translateY(-50%); z-index: 2;
  width: var(--tap-target); height: var(--tap-target); padding: .7rem;
}
.finder-results:has(> .finder-result-reciprocals:not([hidden])) > .finder-date-reset {
  right: calc(50% + var(--finder-card-w) / 2 + 2 * min(var(--quad-card-w, calc(560px * var(--quad-scale, 1) / 7)), 12vw) + 1.85rem);
}
.finder-date-reset svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.finder-date-reset:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.finder-results.triptych > .finder-date-reset,
.finder-results.triptych:has(> .finder-result-reciprocals:not([hidden])) > .finder-date-reset {
  left: 50%; right: auto; top: calc(var(--triptych-main-w) * 1.4 + .75rem);
  transform: translateX(-50%);
}
.finder-results.triptych:has(> .finder-date-reset:not([hidden])) { margin-bottom: calc(var(--tap-target) + .75rem); }
.finder-result-reciprocals { position: absolute; right: calc(50% + var(--finder-card-w) / 2 + .75rem); top: 50%; transform: translateY(-50%); display: flex; gap: .3rem; }
.finder-result-reciprocals[hidden] { display: none; }
