.finder-result-reciprocals [role="button"], #fAbout .spread-card[data-idx] { cursor: pointer; }
.finder-deck {
  display: grid; justify-items: center; gap: .72rem;
  margin: 1.5rem auto 0;
}
.finder-deck-card {
  position: relative; width: var(--finder-card-w); aspect-ratio: 5 / 7;
  display: block; padding: 0; border: 0; border-radius: var(--card-radius); background: transparent; cursor: pointer;
  box-shadow: 0 0 0 1.5px var(--gold), 0 0 14px 2px rgba(199,154,84,.24);
  transform: perspective(650px) rotateY(0deg); transform-style: preserve-3d;
}
.finder-deck-card .card-back {
  background: var(--surface);
}
.finder-deck-card .card-back::before,
.finder-deck-card .card-back .cb-coin { display: none; }
.finder-deck-card:hover { box-shadow: 0 0 0 1.5px var(--gold-ink), 0 0 18px 3px rgba(199,154,84,.36); }
.finder-deck-card:focus-visible { outline: 2px solid var(--gold); outline-offset: 4px; }
.finder.finder-has-selection .finder-deck { position: absolute; visibility: hidden; pointer-events: none; }
.finder.finder-has-selection .finder-results { margin-top: 1.5rem; }
.finder.finder-is-revealing .finder-result.has-card .spread-card { opacity: 0; }
.finder-card-handoff { position: fixed; z-index: 90; pointer-events: none; perspective: 700px; }
.finder-card-handoff-flip { position: relative; width: 100%; height: 100%; transform-style: preserve-3d; will-change: transform; animation: finder-card-flip .64s both; }
.finder-card-handoff-side { position: absolute; inset: 0; overflow: hidden; border-radius: var(--card-radius); backface-visibility: hidden; -webkit-backface-visibility: hidden; }
.finder-card-handoff-back .card-back {
  background: var(--surface);
}
.finder-card-handoff-back .card-back::before,
.finder-card-handoff-back .cb-coin { display: none; }
