.finder-card-handoff-front .spread-card { width: 100%; height: 100%; }
.finder-card-handoff-side { box-shadow: 0 0 0 1.5px var(--gold), 0 0 14px 2px color-mix(in srgb, var(--gold) 35%, transparent); }
@keyframes finder-card-flip {
  0% { transform: translateY(0) rotateY(-12deg) rotateZ(-1deg); animation-timing-function: cubic-bezier(.3,0,.6,1); }
  35% { transform: translateY(-6%) rotateY(8deg) rotateZ(1deg); animation-timing-function: cubic-bezier(.2,.7,.3,1); }
  100% { transform: translateY(0) rotateY(0deg) rotateZ(0deg); }
}
@media (prefers-reduced-motion: reduce) { .finder-deck, .finder-deck-card, .finder-result, .finder-card-handoff-flip { transition: none; animation: none !important; } }
.finder-results.triptych {
