.finder-about-suit:empty,
.finder-about-rank:empty { display: none; }
.finder-about-suit,
.finder-about-rank {
  width: 100%;
  max-width: var(--reading-max-w);
  margin: 0 auto;
  padding: var(--space-4) 0 0;
}
.finder-about-card-heading,
.finder-about-suit-heading,
.finder-about-rank-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: baseline;
  gap: var(--space-3);
}
.finder-about-card-heading h3,
.finder-about-suit-heading h3,
.finder-about-rank-heading h3 {
  display: flex;
  grid-column: 2;
  align-items: center;
  justify-self: center;
  gap: var(--space-2);
  margin: 0;
  font: 500 1rem/1.3 var(--serif);
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--gold-ink);
}
.finder-about-suit-symbol { font-size: 1.25em; line-height: 1; }
.finder-about-suit-symbol.hearts,
.finder-about-suit-symbol.diamonds { color: var(--red); }
.finder-about-suit-element,
.finder-about-rank-label {
  grid-column: 3;
  justify-self: end;
  font: 500 .72rem/1.3 var(--sans);
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--muted);
}
.finder-about-card-note {
  grid-column: 1 / -1;
  justify-self: center;
  margin: .35rem 0 0;
  font: italic 400 .9rem/1.4 var(--serif);
  letter-spacing: .03em;
  color: var(--red);
  text-align: center;
}
.finder-about-suit-keywords,
.finder-about-rank-keywords {
  margin: var(--space-2) 0 var(--space-3);
  font: 500 .76rem/1.5 var(--sans);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--gold-ink);
}
.finder-about-suit-text,
.finder-about-rank-text {
  margin: 0;
  font: 400 clamp(.95rem, 2.6vw, 1.02rem)/1.7 var(--serif);
  color: var(--text);
}
.finder-about.has-longform .finder-about-personality { display: none; }
.finder-about-longform {
  max-width: var(--reading-max-w);
  margin: 0 auto;
  font-family: var(--serif);
  font-size: clamp(.95rem, 2.6vw, 1.02rem);
  line-height: 1.7;
  color: var(--text);
}
.finder-long-section + .finder-long-section {
  margin-top: 1.35rem;
  padding-top: 1.25rem;
}
.finder-long-h {
  margin: 0 0 .7rem;
  font-family: var(--serif);
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--gold-ink);
}
.finder-long-section p,
.finder-long-disclosure-body p { margin: 0 0 .8em; }
.finder-long-section p:last-child,
.finder-long-disclosure-body p:last-child { margin-bottom: 0; }
.finder-long-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: .48rem;
  font-family: var(--sans);
  font-size: .9rem;
  line-height: 1.5;
  color: var(--secondary);
}
.finder-long-list li {
  position: relative;
  padding-left: 1rem;
}
.finder-long-list li::before {
  content: "\2022";
  position: absolute;
  left: 0;
  color: var(--gold);
}
.finder-long-shadows li::before { color: var(--rule-strong); }
.finder-long-explore {
  margin-top: 1.5rem;
  padding-top: 1.25rem;
}
.finder-long-explore-h {
  margin: 0 0 .6rem;
  font-family: var(--serif);
  font-size: .78rem;
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--muted);
}
.finder-long-disclosure { border: 0; }
.finder-long-disclosure summary {
  position: relative;
  min-height: 44px;
  padding: .75rem 2rem .75rem 0;
  cursor: pointer;
  list-style: none;
  font-family: var(--serif);
  color: var(--gold-ink);
}
.finder-long-disclosure summary::-webkit-details-marker { display: none; }
.finder-long-disclosure summary::after {
  content: "+";
  position: absolute;
  right: .2rem;
  top: 50%;
  translate: 0 -50%;
  font-family: var(--sans);
  font-size: 1.1rem;
  color: var(--muted);
}
.finder-long-disclosure[open] summary::after { content: "\2212"; }
.finder-long-disclosure summary:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}
.finder-long-disclosure-body {
  padding: .2rem 0 1rem;
  color: var(--secondary);
}
.finder-about.is-joker .finder-about-personality,
.finder-about.is-joker .finder-about-suit,
.finder-about.is-joker .finder-about-rank { display: none; }
.finder-about.is-relationship .finder-about-inner { display: flex; }
/* The About voice rail only makes sense when there's a delineated reading to
   voice — hide it in the empty state, for the Joker, and in relationship mode. */
.finder-about.is-empty .finder-about-voice,
.finder-about.is-joker .finder-about-voice,
.finder-about.is-relationship .finder-about-voice { display: none; }
/* The rail sits above the reading; keep the modern view's top spacing from
   doubling up with the rail's own bottom margin. */
.finder-about-voice { margin-top: .1rem; }
.finder-about .finder-about-voice { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.finder-about .finder-about-voice .astro-zodiac-tab { padding-inline: .35rem; letter-spacing: .1em; }
.finder-modern-actions {
  display: flex;
  justify-content: center;
  gap: .15rem;
  margin: 0 auto;
  padding-top: .55rem;
}
.finder-modern-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--tap-target);
  padding: .35rem .6rem;
  border: 0;
  background: none;
  color: var(--ink-muted);
  font: 600 .72rem/1 var(--sans);
  letter-spacing: .04em;
  text-transform: none;
  cursor: pointer;
  transition: color var(--ease);
}
.finder-modern-action-btn:hover { color: var(--gold); }
.finder-modern-action-btn.is-active { color: var(--gold); }
.finder-modern-action-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; border-radius: var(--r-sm); }
.finder-modern-details {
  width: 100%;
  margin-top: .15rem;
  padding: .65rem .9rem;
  border: 1px solid var(--border);
  border-radius: var(--r-md);
}
.finder-modern-details[hidden] { display: none; }
.finder-about.is-joker .finder-modern-actions,
.finder-about.is-relationship .finder-modern-actions { display: none; }
.finder-modern-yenlo {
  width: 100%;
  margin-top: .15rem;
  padding: .65rem .9rem;
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  text-align: left;
}
.finder-modern-yenlo[hidden] { display: none; }
.finder-modern-yenlo .olney-panel,
.finder-modern-yenlo .olney-delin,
.finder-modern-yenlo .olney-spread,
.finder-modern-yenlo .olney-plate {
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
}
.finder-modern-yenlo .olney-delin,
.finder-modern-yenlo .olney-spread { max-width: none; }
.finder-modern-yenlo .olney-pl { overflow-wrap: anywhere; }
@media (max-width: 640px) {
}

/* ── Finder Olney panel (added 2026-07-10) ──────────────────────────
   The Richmond 1893 "Mystic Test Book" reading. Two pages on desktop
   (delineation left, engraved plate right); stacks on mobile. Uses the
   site serif (Lora) rather than a dedicated webfont for this reading,
   so there's no extra font-loading hit for this panel. */
.finder-about-olney { color: var(--secondary); }
.olney-panel { padding: .25rem 0 .2rem; }
.olney-sun { display: grid; grid-template-columns: repeat(3, 1fr); gap: .3rem; margin-bottom: .55rem; }
.olney-sun .spread-card { width: 100%; }
.olney-grid { display: flex; flex-direction: column; gap: .3rem; max-width: var(--reading-max-w); margin: 0 auto; }
.olney-row { display: grid; grid-template-columns: repeat(7, 1fr); gap: .3rem; align-items: center; }
.olney-row .spread-card { width: 100%; }
.olney-focus { outline: 2px solid var(--gold); outline-offset: 1px; }
.olney-note { text-align: center; color: var(--muted); font-style: italic; font-size: .9rem; padding: 1.4rem .5rem; }
.olney-delin { max-width: 620px; margin: 0 auto; }
.olney-spread { max-width: 500px; margin: .4rem auto 0; padding-top: 0; }

.olney-bookhead {
  text-align: center; border-bottom: 6px double var(--rule-strong);
  padding-bottom: .8rem; margin-bottom: .9rem;
}
.olney-booktitle {
  font-family: var(--serif); font-weight: 500;
  font-size: .8rem; letter-spacing: .18em; text-transform: uppercase;
  color: var(--gold-ink);
}
.olney-headrow {
  display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center;
  gap: .5rem; margin-top: .55rem;
}
.olney-cardface { width: 3.2rem; margin: 0; grid-column: 1; justify-self: start; }
.olney-vals { grid-column: 2; margin: 0; display: grid; gap: .14rem; justify-items: center; }
.olney-title { grid-column: 3; justify-self: end; max-width: 10rem; margin: 0; color: var(--secondary); font: italic 400 .72rem/1.35 var(--serif); text-align: right; overflow-wrap: anywhere; }
.olney-vals > div { display: flex; justify-content: center; gap: .5rem; align-items: baseline; }
.olney-vals dt {
  font-family: var(--serif); font-size: .55rem;
  letter-spacing: .1em; text-transform: uppercase; color: var(--muted);
}
.olney-vals dt::after { content: ','; }
.olney-vals dd { margin: 0; font-family: var(--mono); font-size: .72rem; color: var(--gold-ink); }
.olney-vals dd::after { content: '.'; color: var(--muted); }

/* Desktop: Richmond's two facing pages — delineation left, engraved
   plate right, split by a centre gutter. Mobile stays stacked. */
@media (min-width: 760px) {
  .olney-panel {
    display: grid; grid-template-columns: 1fr 1fr; gap: 0; align-items: stretch;
  }
  .olney-delin  { max-width: none; margin: 0; padding-right: 1.3rem; border-right: 1px solid var(--border); }
  .olney-spread { max-width: none; margin: 0; border-top: none; padding-top: 0; padding-left: 1.3rem; }
  .olney-spread .olney-plate {
    margin: 0;
    width: auto;
  }
  .olney-platehead { margin-bottom: .14rem; }
  .olney-platehead .olney-head { margin-bottom: 0; }
}

.olney-pl {
  font-family: var(--serif); font-size: .82rem; color: var(--secondary);
  line-height: 1.7; margin: 0 0 .9rem; text-align: center;
}
.olney-pl b {
  font-family: var(--sans); font-size: .56rem; letter-spacing: .1em;
  text-transform: uppercase; color: var(--gold-ink); display: inline; margin-bottom: 0;
}
@media (max-width: 560px) {
  .olney-row, .olney-head, .olney-sun { gap: .16rem; }
  .olney-head { margin-bottom: .55rem; }
  .olney-hlabel {
    font-size: .56rem;
    line-height: 1.34;
    letter-spacing: .07em;
  }
  .olney-horn {
    font-size: .46rem;
    margin: .1rem 0;
    letter-spacing: .12em;
  }
  .olney-hfp {
    font-size: .68rem;
    letter-spacing: .11em;
  }
}

/* ── Grand Spread as Richmond's engraved plate ──────────────────────
   Transparent background so the plate melts into the starfield. Cards
   render in light gold engraving on the dark ground. */
.olney-plate {
  --plate-ink:  var(--gold-ink);
  --plate-rule: var(--muted);
  --plate-gold: var(--gold);
  background: transparent;
  color: var(--plate-ink);
  padding: 1.1rem clamp(.55rem, 2vw, 1.2rem) 1.2rem;
}
.olney-mast { display: flex; align-items: flex-end; justify-content: center; gap: .3rem; flex-wrap: wrap; margin-bottom: .9rem; }
.olney-mast-t {
  font-family: var(--serif); font-weight: 600; font-style: italic;
  font-size: clamp(.82rem, 2.5vw, 1.22rem); line-height: 1; color: var(--plate-ink);
  text-shadow: 0 1px 4px rgba(0,0,0,.5);
  padding-bottom: .25rem; white-space: nowrap;
}
.olney-sunburst { flex: 0 0 auto; width: clamp(64px, 18vw, 96px); height: auto; }
.olney-head {
  display: grid; grid-template-columns: repeat(7, 1fr); align-items: start;
  gap: .3rem; margin-bottom: .16rem;
}
.olney-hside { padding-top: .08rem; }
.olney-hside.left  { grid-column: 1 / span 2; text-align: right; }
.olney-head .olney-sun { grid-column: 3 / span 3; }
.olney-hside.right { grid-column: 6 / span 2; text-align: left; }
.olney-hlabel {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(.5rem, 1.45vw, .62rem); letter-spacing: .06em;
  text-transform: uppercase; line-height: 1.3; color: var(--plate-ink);
}
.olney-horn { font-size: .38rem; color: var(--plate-rule); margin: .06rem 0; letter-spacing: .1em; }
.olney-hfp {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(.56rem, 1.7vw, .74rem); letter-spacing: .1em;
  text-transform: uppercase; color: var(--plate-ink);
}
@media (min-width: 761px) {
  .olney-hlabel {
    font-size: .44rem;
    line-height: 1.22;
    letter-spacing: .05em;
  }
  .olney-horn {
    font-size: .3rem;
    margin: .03rem 0;
    letter-spacing: .08em;
  }
  .olney-hfp {
    font-size: .56rem;
    letter-spacing: .08em;
  }
}
.olney-plate .olney-sun { margin-bottom: 0; }
.olney-plate .olney-grid { max-width: none; gap: .14rem; }
.olney-plate .olney-row  { gap: .14rem; }
.olney-plate .olney-head { gap: .14rem; }
.olney-plate .olney-focus  { outline-color: var(--plate-gold); }

/* Book-style cards: drop the corner rank indices, trim the parchment
   margin so pips fill more of the card. Grown court figure with pips
   pinned toward the corners, matching an engraved-plate look. */
.olney-plate .spread-card .card-corner,
.olney-cardface .card-corner { display: none; }
.olney-plate .card-pips,  .olney-cardface .card-pips { top: 9%; bottom: 9%; left: 8%; right: 8%; }
.olney-plate .pip,        .olney-cardface .pip { font-size: 22cqw; }
.olney-plate .pip.ace,    .olney-cardface .pip.ace { font-size: 52cqw; }
.olney-plate .court-art,  .olney-cardface .court-art { inset: 0; width: 100%; height: 100%; transform: scale(1.08); }
.olney-plate .spread-card > span:first-of-type,
.olney-cardface > span:first-of-type { left: 23% !important; top: 15.5% !important; }
.olney-plate .spread-card > span:last-of-type,
.olney-cardface > span:last-of-type  { left: 77% !important; top: 84.5% !important; }
.olney-spreadname {
  margin-top: .7rem; text-align: center;
  font-family: var(--serif); font-weight: 500;
  font-size: .58rem; letter-spacing: .14em; text-transform: uppercase;
  color: var(--plate-rule);
}

/* ── Finder Life Script panel (2026-07-10) ─────────────────────────
   Seven ruling cards for the picked card, one per planet
   (Neptune → Mercury), plus a compact birth-card stats block. */
.finder-lifescript {
  color: var(--secondary);
  container-type: inline-size;
}
.ls-header { text-align: center; margin: 0 0 .8rem; }
.ls-title {
  margin: 0;
  font-family: var(--sans);
  font-size: .68rem;
  font-weight: 600;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--gold);
}
.ls-lede {
  margin: .35rem 0 0;
  font-family: var(--serif); font-style: italic;
  font-size: .85rem; color: var(--muted);
}
.ls-row {
  --ls-card-w: var(--quad-card-w, calc(560px * var(--quad-scale, 1) / 7));
  display: grid;
  grid-template-columns: repeat(7, minmax(0, var(--ls-card-w)));
  gap: .4rem .3rem;
  justify-content: center;
  justify-items: center;
  align-items: start;
  margin: 0 auto 1.45rem;
  max-width: calc(var(--ls-card-w) * 7 + (.3rem * 6));
}
/* Single-seat connections retain the same seven-column track as full
   connection rows. Placing the lone seat in the centre column guarantees
   that its card has exactly the same width as its seven-card neighbours. */
.ls-connections-wrap .ls-row--single {
  grid-template-columns: repeat(7, minmax(0, var(--ls-card-w)));
}
.ls-connections-wrap .ls-row--single .ls-col {
  grid-column: 4;
}
.ls-stats {
  --ls-card-w: var(--quad-card-w, calc(560px * var(--quad-scale, 1) / 7));
  container-type: inline-size;
  max-width: 620px;
  margin: 0 auto 1.15rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: .8rem;
}
.ls-stat-block {
  text-align: center;
}
.ls-stat-label {
  margin: 0 0 .32rem;
  font-family: var(--sans);
  font-size: .64rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--gold-ink);
}
.ls-stat-text {
  max-width: 32rem;
  margin: 0 auto;
  font-family: var(--mono);
  font-size: .68rem;
  line-height: 1.5;
  color: var(--muted);
}
.ls-date-grid {
  display: grid;
  gap: .22rem;
  justify-items: center;
  max-width: 32rem;
  margin: 0 auto;
}
.ls-date-row {
  display: flex;
  flex-wrap: nowrap;
  justify-content: center;
  gap: .42rem;
}
.ls-date-item {
  appearance: none;
  border: 0;
  border-radius: var(--r-sm);
  padding: .04rem .14rem;
  background: transparent;
  font-family: var(--mono);
  font-size: .68rem;
  line-height: 1.45;
  color: var(--muted);
  white-space: nowrap;
}
.ls-stat-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: .35rem .45rem;
}
.ls-stat-chip {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  padding: .18rem .5rem;
  border: 1px solid var(--rule);
  border-radius: 999px;
  font-family: var(--sans);
  font-size: .68rem;
  letter-spacing: .03em;
  color: var(--text);
  background: rgba(255,255,255,.03);
}
.ls-planet-link {
  cursor: pointer;
  transition: border-color var(--ease), color var(--ease), background var(--ease), transform var(--ease);
}
.ls-planet-link:hover,
.ls-planet-link:focus-visible {
  border-color: var(--gold);
  color: var(--gold);
  background: rgba(199,154,84,.1);
  transform: translateY(-1px);
}
.ls-planet-link:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.ls-stat-chips .ls-stat-chip,
.ls-prc-sign .ls-stat-chip,
.ls-prc-slot .ls-stat-chip {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}
.ls-stat-chips .ls-planet-link:hover,
.ls-stat-chips .ls-planet-link:focus-visible {
  border-color: transparent;
  background: transparent;
}
.about-planet-info {
  max-width: 38rem;
  margin: .75rem auto 0;
  text-align: center;
}
.ls-stat-chips.qcp-planets {
  flex-wrap: nowrap;
  justify-content: flex-start;
  overflow-x: auto;
  max-width: 100%;
  width: max-content;
  margin-inline: auto;
  padding: var(--space-2);
  gap: var(--space-2);
}
.qcp-planets .ls-planet-link {
  flex: 0 0 auto;
  flex-direction: column;
  justify-content: center;
  min-height: var(--tap-target);
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--rule-strong);
  border-radius: var(--r-sm);
  background: var(--surface);
}
.qcp-planets .ls-planet-link small { color: var(--gold-ink); }
.qcp-planets .ls-planet-link:hover,
.qcp-planets .ls-planet-link:focus-visible,
.qcp-planets .ls-planet-link[aria-expanded="true"] {
  border-color: var(--gold);
  background: var(--surface-alt);
  color: var(--gold-ink);
}
.about-planet-info[hidden] { display: none; }
.about-planet-head {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .65rem;
  text-align: center;
}
.about-planet-glyph {
  color: var(--gold);
  font: 1.7rem/1 var(--serif);
}
.about-planet-head h4 {
  margin: 0;
  color: var(--text);
  font: 500 1.15rem/1.15 var(--serif);
}
.about-planet-head p {
  margin: .18rem 0 0;
  color: var(--gold-ink);
  font: .6rem/1.2 var(--sans);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.about-planet-synopsis,
.about-planet-copy {
  max-width: 34rem;
  margin: .8rem auto 0;
  color: var(--secondary);
  font: .88rem/1.6 var(--serif);
}
.about-planet-synopsis {
  color: var(--gold-ink);
  font-style: italic;
}
.about-planet-copy { margin-top: .55rem; }
.mini-card,
.cal-chip,
.bi-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--mini-card-min-w);
  block-size: var(--mini-card-h);
  padding: 0 var(--mini-card-pad-x);
  border: 1px solid rgba(75,57,31,.18);
  border-radius: var(--card-radius);
  font-family: var(--serif);
  font-size: clamp(.44rem, 1.35vw, var(--mini-card-font));
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;
  background: rgba(253,250,245,.88);
  color: var(--card-dark);
}
