.ls-connection-options > summary:hover,
.ls-connection-options[open] > summary { border-color: var(--gold-ink); color: var(--gold-ink); }
.ls-connection-options > summary:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.ls-connection-options-panel {
