  font: 500 .66rem/1.3 var(--sans);
}
.ls-prc-connection-system legend {
  float: left;
  margin-right: var(--space-2);
  color: var(--muted);
}
.ls-prc-connection-system label { display: inline-flex; align-items: center; gap: .3rem; cursor: pointer; }
.ls-prc-connection-system input { accent-color: var(--gold); }
.ls-prc-connection-system:disabled,
.ls-prc-pluto-toggle:has(input:disabled) { opacity: .5; }
.ls-prc-pluto-toggle { display: inline-flex; align-items: center; gap: .4rem; color: var(--secondary); font: 500 .66rem/1.3 var(--sans); cursor: pointer; }
.ls-prc-pluto-toggle input { accent-color: var(--gold); }
.ls-connection-details,
.ls-cusp-connections,
.ls-prc-connections {
  margin: .35rem auto 0;
  max-width: 620px;
}
.ls-connection-details > summary,
.ls-cusp-connections > summary,
.ls-prc-connections > summary {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: var(--tap-target);
  color: var(--secondary);
  cursor: pointer;
  font: 600 .66rem/1.2 var(--sans);
  letter-spacing: .08em;
  list-style: none;
  text-align: center;
  text-transform: uppercase;
}
.ls-connection-details > summary::-webkit-details-marker,
.ls-cusp-connections > summary::-webkit-details-marker,
.ls-prc-connections > summary::-webkit-details-marker { display: none; }
.ls-connection-details > summary::after,
.ls-cusp-connections > summary::after,
.ls-prc-connections > summary::after { content: "+"; margin-left: .45rem; font-size: .9rem; }
.ls-connection-details[open] > summary::after,
.ls-cusp-connections[open] > summary::after,
.ls-prc-connections[open] > summary::after { content: "−"; }
.ls-connection-details > summary {
  inline-size: var(--tap-target);
  margin-inline: auto;
  padding: 0;
}
.ls-connection-details > summary::after { display: none; }
.ls-connection-details > summary span {
  color: var(--secondary);
  font: 1.35rem/.8 var(--sans);
  transition: transform var(--ease), color var(--ease);
}
.ls-connection-details > summary:hover span { color: var(--text); }
.ls-connection-details[open] > summary span { transform: rotate(180deg); }
.ls-connection-details > summary:hover,
.ls-cusp-connections > summary:hover,
.ls-prc-connections > summary:hover { color: var(--text); }
.ls-connection-details > summary:focus-visible,
.ls-cusp-connections > summary:focus-visible,
.ls-prc-connections > summary:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; border-radius: var(--r-sm); }
.ls-connection-details[open] { margin-top: .2rem; }
.ls-connection-assumption,
.ls-connection-empty {
  max-width: 34rem;
  margin: 0 auto 1rem;
  color: var(--muted);
  font: .76rem/1.55 var(--sans);
  text-align: center;
}
.ls-connection-empty { color: var(--secondary); }
.ls-card.ls-conn-pick,
.ls-connections-wrap .ls-col[data-planet="Sun"] .ls-card,
.nc-alternate-sun .spread-card {
  border-color: var(--gold);
  box-shadow: 0 0 0 2px var(--gold), 0 0 0 4px rgba(205,168,95,.18),
              0 0 14px 2px rgba(205,168,95,.5);
}
@media (max-width: 560px) {
  .ls-row {
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: .18rem;
    max-width: 100%;
  }
  /* Match the full connection row's responsive fractional track. */
  .ls-connections-wrap .ls-row--single {
    grid-template-columns: repeat(7, minmax(0, 1fr));
    max-width: 100%;
