  .ls-connection-title { font-size: .9rem; }
  .ls-connection-gloss { font-size: .86rem; }
}

/* ── Finder Cycles panel ───────────────────────────────────────────
   Five personal cards: 13-Year / 7-Year / Yearly / 52-Day / Daily.
   Selecting a cycle opens its reading inline; controls move between
   available readings in the viewed timeline. */
.finder-intime {
  --finder-tool-size: var(--tap-target);
  margin-top: var(--about-section-gap, var(--space-5));
  color: var(--secondary);
}
.finder-reading-panel.finder-intime { margin-top: 0; }
.finder-panels.is-relationship .finder-intime { display: none; }
.finder-intime .it-empty { display: none; }
.finder-intime.is-empty .it-inner { display: none; }
.finder-intime.is-empty .it-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .65rem;
  margin: 0 auto;
  text-align: center;
  color: var(--muted);
}
.it-date-favorites[hidden] { display: none; }
.it-date-favorites:not([hidden]) {
  display: grid;
  gap: .25rem;
  width: min(30rem, 100%);
  margin: -.15rem auto .55rem;
  max-height: min(14rem, 48vh);
  overflow: auto;
  padding: .45rem;
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  background:
    linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.03)),
    var(--bg);
  box-shadow: var(--sh-md);
}
.it-displacement-figure { position: relative; width: min(100%, 34rem); margin: .25rem auto 0; }
.it-displacement-wheel { width: 100%; }
.it-displacement-wheel-svg { display: block; width: 100%; height: auto; }
.it-wheel-orbit { fill: none; stroke: var(--rule-strong); stroke-width: 1; stroke-dasharray: 2 4; }
.it-wheel-card rect { fill: var(--card-paper); stroke: var(--bronze); stroke-width: 1; }
.it-wheel-card text { fill: currentColor; font: 600 8.5px/1 var(--serif); }
.it-wheel-card--red { color: var(--red); }
.it-wheel-card--dark { color: var(--card-dark); }
.it-wheel-favorites-toggle {
  position: absolute;
  z-index: 2;
  top: 32%;
  left: 50%;
  display: grid;
  place-items: center;
  width: var(--finder-tool-size);
  height: var(--finder-tool-size);
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 50%;
  background:
    linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.03)),
    rgba(17,12,33,.38);
  color: var(--gold-ink);
  cursor: pointer;
  font: 1.15rem/1 var(--serif);
  transform: translate(-50%, -50%);
}
.it-wheel-favorites-toggle:hover,
.it-wheel-favorites-toggle[aria-expanded="true"] { border-color: var(--gold-ink); background: var(--gold-light); }
.it-date-favorites-toggle {
  position: absolute;
  inset: 50% auto auto .2rem;
  z-index: 3;
  display: grid;
  place-items: center;
  width: var(--finder-tool-size);
  height: var(--finder-tool-size);
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: transparent;
  color: var(--gold-ink);
  cursor: pointer;
  font: 1.1rem/1 var(--serif);
  transform: translateY(-50%);
}
.it-date-action-btn {
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 50%;
  background: transparent;
  color: var(--secondary);
  cursor: pointer;
  transition: border-color var(--ease), color var(--ease), background var(--ease);
}
.it-date-action-btn:hover,
.it-date-action-btn.is-active { border-color: var(--gold); color: var(--gold); background: rgba(199,154,84,.1); }
.it-date-action-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.it-date-action-btn svg { width: 1rem; height: 1rem; }
.it-date-share-toggle {
  position: absolute;
  inset: 50% .2rem auto auto;
  z-index: 3;
  width: var(--finder-tool-size);
  height: var(--finder-tool-size);
  padding: 0;
  transform: translateY(-50%);
}
.it-date-favorites-toggle:hover,
.it-date-favorites-toggle[aria-expanded="true"] { border-color: var(--gold-ink); background: var(--gold-light); }
.it-wheel-favorites-toggle:focus-visible,
.it-date-favorites-toggle:focus-visible,
.it-wheel-favorite:focus-visible,
.it-favorites [data-it-open-favorites]:focus-visible,
.it-date-favorites [data-it-open-favorites]:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.it-favorites[hidden] { display: none; }
.it-favorites:not([hidden]) {
  position: absolute;
  z-index: 3;
  top: calc(50% + 1.8rem);
  left: 50%;
  display: grid;
  gap: .25rem;
  width: min(17rem, calc(100% - 2rem));
  max-height: min(12rem, 38vw);
  overflow: auto;
  padding: .45rem;
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  background:
    linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.03)),
    var(--bg);
  box-shadow: var(--sh-md);
  transform: translateX(-50%);
}
.it-wheel-favorite {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  width: 100%;
  min-height: var(--tap-target);
  padding: .45rem .55rem;
  border: 0;
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--text);
  cursor: pointer;
  text-align: left;
  font: 500 .7rem/1.3 var(--sans);
}
.it-wheel-favorite:hover { background: var(--gold-light); }
.it-wheel-favorite small { color: var(--muted); white-space: nowrap; font: 500 .62rem/1.3 var(--sans); }
.it-wheel-favorites-empty { margin: .4rem; color: var(--secondary); font: .78rem/1.4 var(--sans); text-align: center; }
.it-favorites [data-it-open-favorites] {
  min-height: var(--tap-target);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--gold-ink);
  cursor: pointer;
  font: 600 .62rem/1.2 var(--sans);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.it-date-favorites [data-it-open-favorites] {
  min-height: var(--tap-target);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--gold-ink);
  cursor: pointer;
  font: 600 .62rem/1.2 var(--sans);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.it-header { text-align: center; margin-bottom: 1rem; }
.it-row-wrap {
  --it-card-w: var(--ls-card-w);
  --it-card-gap: .55rem;
  margin-top: 1rem;
  width: 100%;
  padding: var(--space-2);
  overflow-x: auto;
  overscroll-behavior-x: contain;
  -webkit-overflow-scrolling: touch;
}
.it-row {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, var(--it-card-w)));
  gap: var(--it-card-gap);
  justify-content: center;
  justify-items: center;
  align-items: start;
  margin: 0 auto;
  max-width: calc(var(--it-card-w) * 5 + (var(--it-card-gap) * 4));
}
.it-col {
  display: flex; flex-direction: column; align-items: center; gap: .3rem;
  min-inline-size: 0; width: 100%;
}
.it-planet-glyph {
  font-size: 1rem; color: var(--gold-ink); line-height: 1;
}
.it-planet-glyph-empty { opacity: .3; font-size: .5rem; }
.it-label {
  font-family: var(--sans); font-size: .62rem; font-weight: 600;
  letter-spacing: .12em; text-transform: uppercase;
  color: var(--gold-ink);
  min-block-size: 2.4em;
  display: grid;
  place-items: center;
  text-align: center;
  line-height: 1.2;
}
.it-card { width: 100%; }
.it-card {
  padding: 0;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease;
}
.it-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--sh-md);
}
.it-card.is-active {
  border-color: var(--gold);
  box-shadow: 0 0 0 2px var(--gold), 0 0 0 4px rgba(205,168,95,.18), 0 0 14px 2px rgba(205,168,95,.45);
}
.it-planet-name {
  font-family: var(--serif); font-style: italic;
  font-size: .72rem; color: var(--muted);
  min-block-size: 1.2em;
  line-height: 1.2;
  text-align: center;
}
.it-sub {
  font-family: var(--mono); font-size: .58rem;
  color: var(--secondary); letter-spacing: .04em;
  min-block-size: 2.5em;
  line-height: 1.25;
  text-align: center;
}
.it-expand,
.it-expand-placeholder {
  display: grid;
  place-items: center;
  width: 1.45rem;
  height: 1.2rem;
  margin: .08rem auto 0;
}
.it-expand {
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--gold);
  font: 700 .9rem/1 var(--sans);
  cursor: pointer;
}
.it-expand:hover,
.it-expand:focus-visible {
  background: rgba(199,154,84,.12);
  outline: 1px solid rgba(217,183,106,.55);
}
.it-sequence {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, calc(var(--it-card-w) * .78)));
  justify-content: center;
  gap: calc(var(--it-card-gap) * .72);
  margin: .9rem auto 0;
  max-width: calc((var(--it-card-w) * .78) * 7 + (var(--it-card-gap) * .72 * 6));
}
.it-seq-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .16rem;
  min-width: 0;
}
.it-seq-head {
  display: grid;
  justify-items: center;
  gap: .08rem;
  min-height: 2.15rem;
}
.it-seq-card {
  width: 100%;
  box-shadow: 0 0 0 1px rgba(217,183,106,.18);
}
.it-seq-col.is-current .it-seq-card {
  box-shadow: 0 0 0 2px var(--gold), 0 0 16px rgba(217,183,106,.48);
}
.it-seq-label {
  font: 700 .5rem/1 var(--sans);
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--muted);
}
.it-seq-date {
  min-height: 1.1em;
  font: 600 .5rem/1.1 var(--sans);
  letter-spacing: .04em;
  color: var(--secondary);
  white-space: nowrap;
}
.it-empty-note {
  max-width: 28rem;
  margin: 0 auto;
  text-align: center;
  font-family: var(--serif);
  font-size: .96rem;
  line-height: 1.65;
  color: var(--secondary);
}
.it-empty-note b {
  color: var(--gold-ink);
  font-weight: 600;
}
.it-wheel-center {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 2;
  width: max-content;
  max-width: calc(100% - 4.5rem);
  margin: 0;
  transform: translate(-50%, -50%);
}
.it-birthday-row {
  position: sticky;
  top: calc(var(--space-2) + env(safe-area-inset-top));
  z-index: 8;
  width: min(100%, 30rem);
  margin: 0 auto .45rem;
}
.it-birthday-top {
  width: fit-content;
  max-width: min(100%, 20rem);
  margin: 0 auto;
}
.it-wheel-date-form {
  margin: 0;
}
.it-wheel-datepair {
  grid-template-columns: 3.2rem auto 3.2rem auto 4.5rem;
  width: max-content;
  max-width: 100%;
}
.it-wheel-year-wrap { width: 4.5rem; }
.it-reading {
  --it-reading-head-h: 3.85rem;
  max-width: 42rem;
  margin: 1.15rem auto 0;
  text-align: center;
  padding: .25rem 1rem 0;
  display: flex;
  flex-direction: column;
  touch-action: pan-y;
}
.it-reading-head {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  margin-bottom: .75rem;
  min-height: var(--it-reading-head-h);
}
.it-reading-head-copy {
  display: flex;
  flex-direction: column;
  gap: .25rem;
  align-items: center;
  text-align: center;
  flex: 1 1 auto;
  min-width: 0;
}
.it-reading-shift {
  width: var(--tap-target);
  height: var(--tap-target);
  flex: 0 0 auto;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.16);
  background: transparent;
  color: var(--gold-ink);
  font-family: var(--sans);
  font-size: 1.05rem;
  line-height: 1;
  cursor: pointer;
  transition: border-color var(--ease), color var(--ease), background var(--ease), transform var(--ease);
}
.it-reading-shift:hover {
  border-color: var(--gold);
  color: var(--gold);
  background: rgba(199,154,84,.08);
  transform: translateY(-1px);
}
.it-reading-shift:disabled,
.it-reading-shift.is-disabled {
  opacity: .28;
  cursor: not-allowed;
  border-color: rgba(255,255,255,.08);
}
.it-reading-shift:disabled:hover,
.it-reading-shift.is-disabled:hover {
  color: var(--gold-ink);
  background: transparent;
  transform: none;
}
.it-reading-kicker {
  font-family: var(--mono);
  font-size: .62rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--gold-ink);
}
.it-reading-title {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.08rem;
  font-weight: 500;
  line-height: 1.35;
  overflow-wrap: anywhere;
  color: var(--text);
}
.it-reading-meta {
  font-family: var(--serif);
  font-style: italic;
  font-size: .84rem;
  color: var(--muted);
}
.it-reading-copy {
  overflow: visible;
  font-family: var(--serif);
  font-size: .98rem;
  line-height: 1.72;
  color: var(--secondary);
}
.it-reading-copy p {
  margin: 0;
}
.it-reading-copy p + p { margin-top: var(--space-3); }
@media (max-width: 560px) {
  .it-row { --it-card-gap: .22rem; }
  .it-row-wrap {
    padding: var(--space-2);
    scroll-padding-inline: .35rem;
    scroll-snap-type: x proximity;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--gold) 60%, transparent) transparent;
  }
  .it-col { scroll-snap-align: center; }
  .it-label { font-size: .55rem; }
  .it-planet-name { font-size: .62rem; }
  .it-sub { font-size: .52rem; }
  .it-sequence {
    grid-template-columns: repeat(7, minmax(0, calc(var(--it-card-w) * .74)));
    gap: .16rem;
    max-width: none;
  }
  .it-expand-placeholder { height: .8rem; }
  .it-reading {
    --it-reading-head-h: 3.4rem;
    padding: .9rem .8rem .9rem;
  }
  .it-reading-head { gap: .5rem; }
  .it-reading-shift {
    font-size: .95rem;
  }
  .it-reading-title { font-size: 1rem; }
  .it-reading-copy { font-size: .92rem; line-height: 1.64; }
}

/* Solar-day birth-card adjustment. */
.it-solar {
  margin-top: .3rem;
  padding: .2rem 0 0;
  text-align: center;
}
.ls-stats > .it-solar {
  width: min(100%, 34rem);
  margin: .9rem auto 0;
  min-width: 0;
  max-width: 100%;
}
.it-solar-title { margin-bottom: .5rem; }
.solar-time-adjustment {
  width: min(100%, 34rem);
  margin: .15rem auto 0;
  padding-top: 0;
}
.finder-modern-actions + .solar-time-adjustment {
  margin-top: calc(var(--about-section-gap, var(--space-5)) * -1 + .15rem);
}
.it-solar-body {
  width: 100%; margin: 0 auto; max-width: 460px; min-width: 0;
  text-align: center;
}
.it-solar-intro {
  font-family: var(--serif); font-style: italic;
  font-size: .92rem; line-height: 1.6; color: var(--muted);
  margin: 0 0 .9rem;
}
.it-solar-fields {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .75rem;
}
.it-solar-field {
  display: flex; flex-direction: column; align-items: flex-start; gap: .28rem;
  flex: 1 1 0; min-width: 0;
  font-family: var(--sans); font-size: .6rem; letter-spacing: .1em;
  text-transform: uppercase; color: var(--gold-ink);
}
.it-solar-field input {
  font-family: var(--sans); font-size: .95rem; letter-spacing: normal;
  text-transform: none; color: var(--text);
  background: var(--band); border: 1px solid var(--rule-strong);
  border-radius: var(--r-sm); padding: .4rem .55rem; width: 100%; min-width: 0;
  height: 2.65rem; box-sizing: border-box;
}
.it-solar-field input:focus { outline: 2px solid var(--gold); outline-offset: 1px; }
.it-solar-out { width: 100%; min-width: 0; max-width: 100%; margin-top: 1.1rem; }
.sol-hint {
  font-family: var(--serif); font-style: italic;
  font-size: .9rem; color: var(--muted); margin: 0;
}
.sol-verdict {
  font-family: var(--serif); font-size: 1rem; line-height: 1.6;
  color: var(--secondary); margin: 0 auto .9rem; max-width: 420px;
}
.sol-verdict strong { color: var(--gold-ink); font-weight: 600; }
.sol-true-time {
  margin: -.35rem auto .9rem;
  color: var(--muted);
  font-family: var(--sans);
  font-size: .7rem;
  letter-spacing: .03em;
}
.sol-true-time strong { color: var(--gold-ink); font-weight: 600; }
.sol-cards {
  display: flex; justify-content: center; align-items: flex-start; gap: 1.2rem;
  /* The cards are content-sized and don't shrink, so wrap is the safety net
     that keeps an unusually long pair off the page's horizontal scroll. */
  flex-wrap: wrap;
  width: 100%;
  container-type: inline-size;
}
.sol-card {
  /* Use the same shared base width as the main planetary ruling card. The
     narrow-screen override below mirrors its seven-column calculation without
     inheriting that percentage token into this card's own flex box. */
  --solar-card-w: var(--quad-card-w, calc(560px * var(--quad-scale, 1) / 7));
  /* Sized to its CONTENT, not to the card face. The face keeps the shared
     Quadrations width below, but the label and name are free to run wider
     than it — pinning the column to --solar-card-w wrapped every two-word
     card name ("Nine of / Clubs") onto a second line. align-items: center
     keeps the face centred under the wider name. */
  display: flex; flex: 0 0 auto;
  flex-direction: column; align-items: center; gap: .45rem;
  min-width: 0;
}
.sol-card .sol-card-face {
  width: var(--solar-card-w);
  max-width: var(--solar-card-w);
  min-inline-size: 0;
  flex: 0 0 auto;
}
@media (max-width: 560px) {
  .sol-card { --solar-card-w: calc((100cqw - (.18rem * 6)) / 7); }
}
.sol-card.dimmed { opacity: .5; }
.sol-card-label {
  font-family: var(--sans); font-size: .58rem; letter-spacing: .1em;
  text-transform: uppercase; color: var(--gold-ink);
}
.sol-card-name {
  font-family: var(--serif); font-size: 1rem; color: var(--text);
  /* Longest real name is "Queen of Diamonds"; the cap is a backstop so a
     surprise string can still wrap rather than blow the row out. */
  max-width: 11rem;
  text-align: center;
  text-wrap: balance;
}
/* Two cards (clock + solar) must still sit side by side on the narrowest
   phones, where two full names at 1rem would overflow the row. */
@media (max-width: 380px) {
  .sol-card-name { font-size: .82rem; }
}

/* ── Cycles date context (2026-07-10, simplified 2026-07-13) —
   clickable date label (opens the hidden native date input) plus a
   "Today" reset that only shows once you've scrolled away from today. */
.it-date-shell {
  position: relative;
  max-width: min(100%, 30rem);
  width: 100%;
  margin: 0 auto .8rem;
}
.it-date-head {
  position: relative;
  display: block;
}
.it-date-row { position: relative; }
.it-date-label {
