  width: 5.7rem; text-align: center;
  min-height: 100%;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
}
.it-date-today.visible {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
}
.it-date-today:hover {
  color: var(--gold-ink);
}
@media (max-width: 420px) {
