/* ── Persistent utility dock ─────────────────────────────────────── */
body { padding-bottom: calc(4.9rem + env(safe-area-inset-bottom)); }
.utility-dock {
  position: fixed;
  z-index: 80;
  left: 50%;
  bottom: max(.6rem, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  width: min(calc(100% - 1rem), 31rem);
  padding: .3rem;
  transform: translateX(-50%);
  border: 1px solid var(--rule-strong);
  border-radius: calc(var(--r-sm) + .35rem);
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  box-shadow: 0 .65rem 2rem rgba(0,0,0,.32);
  backdrop-filter: blur(18px);
}
.utility-dock-btn {
  position: relative;
  display: grid;
  place-items: center;
  gap: .18rem;
  min-width: 0;
  min-height: 3.65rem;
  padding: .3rem .2rem;
  border: 0;
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font: 600 .56rem/1 var(--sans);
  letter-spacing: .08em;
  text-transform: uppercase;
  transition: color var(--ease), background var(--ease);
}
.utility-dock-btn::after {
  position: absolute;
  right: 50%;
  bottom: .12rem;
  width: 1rem;
  height: 2px;
  border-radius: 2px;
  background: var(--gold);
  content: "";
  opacity: 0;
  transform: translateX(50%) scaleX(.55);
  transition: opacity var(--ease), transform var(--ease);
}
.utility-dock-btn:hover,
.utility-dock-btn.is-active { color: var(--gold); background: var(--gold-light); }
.utility-dock-btn.is-active::after { opacity: 1; transform: translateX(50%) scaleX(1); }
.utility-dock-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: -2px; }
.utility-dock-btn:disabled { opacity: .38; cursor: not-allowed; }
.utility-dock-icon { display: block; width: 1.35rem; height: 1.35rem; color: var(--gold-ink); font: 1.25rem/1 var(--serif); }
.utility-dock-icon--finder { width: 1.35rem; }
.utility-dock-icon--finder svg { display: block; width: 100%; height: 100%; overflow: visible; fill: none; stroke: currentColor; stroke-width: 1; stroke-linecap: round; stroke-linejoin: round; }
.utility-dock-icon--finder .finder-icon-main { fill: currentColor; }
.utility-dock-icon--finder .finder-icon-mark { stroke: var(--bg); stroke-width: 1.2; }
.utility-dock-icon--cycles,
.utility-dock-icon--quad { width: 1.35rem; }
.utility-dock-icon--cycles svg,
.utility-dock-icon--quad svg { display: block; width: 100%; height: 100%; overflow: visible; fill: none; stroke: currentColor; stroke-width: 1; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 760px) {
  body { padding-bottom: 5.7rem; }
  .utility-dock { bottom: 1rem; width: min(29rem, calc(100% - 2rem)); }
  .utility-dock-btn { min-height: 3.4rem; grid-auto-flow: column; justify-content: center; gap: .42rem; }
  .utility-dock-icon { height: auto; }
}
.finder-rel-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--sans);
  font-size: 1.1rem;
  font-weight: 500;
  line-height: 1;
  text-align: center;
  letter-spacing: 0;
  vertical-align: middle;
  padding-bottom: .02rem;
}
.finder-tool-btn--icon svg {
