  border-radius: 999px; background: var(--gold); color: var(--accent);
  font-size: .55rem; font-weight: 700; line-height: 15px; text-align: center;
  display: none;
}
.finder-tool-badge.visible { display: block; }

.finder-tray-wrap {
  display: grid; grid-template-rows: 0fr;
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  transition:
    grid-template-rows .18s ease,
    opacity .12s ease,
    visibility 0s linear 0s;
  width: min(100%, var(--control-rail-w));
  margin-inline: auto;
}
