  width: min(100%, calc(var(--control-rail-w) * .7));
}
.finder-tray-wrap.open {
  grid-template-rows: 1fr;
  margin-top: 1.25rem;
  opacity: 1;
  pointer-events: auto;
  visibility: visible;
  transition:
    grid-template-rows .35s ease,
    opacity .18s ease,
    visibility 0s linear 0s;
}
.finder-tray-min { overflow: hidden; min-height: 0; }
.finder-tray {
  padding: 0;
}
@media (prefers-reduced-motion: reduce) { .finder-tray-wrap { transition: none; } }
@media (prefers-reduced-motion: reduce) { .utility-slide-panel { transition: none; } }

.bday-inline-head {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: var(--space-3); margin-bottom: .7rem;
  padding-bottom: .7rem;
  border-bottom: 1px solid var(--rule);
}
.bday-inline-title { color: var(--gold-ink); font: 700 .62rem/1 var(--sans); letter-spacing: .14em; text-transform: uppercase; }
.bday-heading { display: flex; align-items: baseline; flex-wrap: wrap; gap: .55rem; }
.bday-count { color: var(--muted); font: .68rem/1.2 var(--sans); }
.bday-head-actions { display: flex; align-items: center; gap: .45rem; }
.bday-more-menu { position: relative; }
.bday-more-menu > summary {
