.bday-more-menu > summary:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.bday-more-menu > summary svg { width: .7rem; height: .7rem; fill: none; stroke: currentColor; stroke-width: 1.5; transition: transform .16s ease; }
.bday-more-menu[open] > summary svg { transform: rotate(180deg); }
.bday-more-menu-panel {
  position: absolute; z-index: 8; top: calc(100% + .25rem); right: 0; display: grid; min-width: 9.5rem;
  padding: .25rem; border: 1px solid var(--rule-strong); border-radius: var(--r-sm);
  background: var(--surface); box-shadow: var(--sh-md);
