.bday-info-btn { width: 1.8rem; height: 1.8rem; border: 1px solid var(--border); border-radius: 50%; background: transparent; color: var(--gold-ink); font: 600 .75rem/1 var(--serif); cursor: pointer; }
.bday-info-btn:hover, .bday-info-btn[aria-expanded="true"] { border-color: var(--gold); color: var(--gold); background: var(--gold-light); }

