}
.birth-tag-option.is-selected { border-color: var(--gold); color: var(--gold-ink); background: rgba(199,154,84,.1); }
.birth-tag-option:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.birth-more-toggle {
  margin: .58rem auto 0;
  display: block;
  border: 0;
  background: transparent;
  color: var(--gold-ink);
  font-family: var(--sans);
  font-size: .62rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  cursor: pointer;
}
