.bday-search input:focus { border-color: var(--gold); outline: 0; box-shadow: 0 0 0 2px rgba(199,154,84,.16); }
.bday-sort { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: .5rem; margin: 0 0 .65rem; }
.bday-inline-head { display: grid; grid-template-columns: minmax(0, 1fr); gap: .65rem; }
.bday-heading { justify-content: space-between; }
.bday-head-actions { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; width: 100%; gap: .45rem; }
.bday-head-actions .bday-sort { min-width: 0; margin: 0; }
.bday-head-actions .bday-sort label { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.bday-head-actions .bday-sort select { width: 100%; min-width: 0; min-height: var(--tap-target); }
