.bday-sort[hidden] { display: none; }
.bday-sort label { color: var(--muted); font: 500 .62rem/1.2 var(--sans); letter-spacing: .08em; text-transform: uppercase; }
.bday-sort select {
  min-height: 1.9rem; padding: .35rem .6rem; border: 1px solid var(--border); border-radius: var(--r-md);
  background: var(--surface); color: var(--text); font: .72rem var(--sans);
