.bday-sort select:focus-visible { border-color: var(--gold); outline: 2px solid rgba(199,154,84,.3); outline-offset: 2px; }
.bday-tags-toggle {
  display: inline-flex; align-items: center; gap: .35rem; min-height: 1.9rem; padding: .35rem .6rem;
  border: 1px solid var(--border); border-radius: var(--r-md); background: transparent; color: var(--secondary);
  cursor: pointer; font: .72rem var(--sans);
}
.bday-tags-toggle:hover,
.bday-tags-toggle[aria-expanded="true"] { border-color: var(--gold); color: var(--gold-ink); }
.bday-tags-toggle:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.bday-tags-toggle svg { width: .7rem; height: .7rem; fill: none; stroke: currentColor; stroke-width: 1.5; transition: transform .16s ease; }
.bday-tags-toggle[aria-expanded="true"] svg { transform: rotate(180deg); }
.bday-active-filters { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: .5rem; margin: -.15rem 0 .7rem; }
.bday-active-filters[hidden] { display: none; }
.bday-active-filter-list { display: flex; flex: 1; flex-wrap: wrap; gap: .3rem; }
.bday-active-filter { padding: .24rem .45rem; border: 1px solid var(--rule); border-radius: 999px; color: var(--muted); font: .62rem/1.25 var(--sans); overflow-wrap: anywhere; }
.bday-clear-filters { padding: .25rem .15rem; border: 0; background: transparent; color: var(--gold-ink); cursor: pointer; font: 600 .62rem/1.25 var(--sans); text-decoration: underline; text-underline-offset: .16em; }
.bday-clear-filters:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.bday-tag-filters { display: flex; flex-wrap: wrap; justify-content: center; gap: .4rem; margin: 0 0 .75rem; }
.bday-tag-filter,
.birth-tag {
  border: 1px solid var(--border); border-radius: 999px; background: transparent; color: var(--secondary);
  font: 600 .64rem/1.15 var(--sans); letter-spacing: .04em;
}
.bday-tag-filter { min-height: 1.75rem; padding: .35rem .55rem; cursor: pointer; }
.bday-tag-filter:hover,
.bday-tag-filter.is-active { border-color: var(--gold); color: var(--gold-ink); background: rgba(199,154,84,.08); }
.bday-tag-filter:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.bday-tag-create {
  min-height: 1.75rem; padding: .35rem .55rem;
  border: 1px dashed var(--border); border-radius: 999px;
  background: transparent; color: var(--gold-ink); cursor: pointer;
  font: 600 .64rem/1.15 var(--sans); letter-spacing: .04em;
}
.bday-tag-create:hover { border-color: var(--gold); color: var(--gold); }
.bday-tag-manager { display: grid; gap: .55rem; width: 100%; padding: .55rem; border-top: 1px solid var(--rule); }
.bday-tag-manager[hidden] { display: none; }
.bday-managed-tag-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr)); gap: .35rem; }
.bday-managed-tag { display: flex; align-items: center; justify-content: space-between; gap: .45rem; padding: .3rem .45rem; border: 1px solid var(--rule); border-radius: var(--r-sm); color: var(--secondary); font: .68rem/1.25 var(--sans); }
.bday-managed-tag button { flex-shrink: 0; padding: .2rem .35rem; border: 0; border-radius: var(--r-sm); background: transparent; color: var(--muted); cursor: pointer; font: 600 .62rem/1.2 var(--sans); }
.bday-managed-tag button:hover { color: #e98a8a; background: rgba(233,138,138,.1); }
.bday-managed-tag button:focus-visible { outline: 2px solid var(--gold); outline-offset: 1px; }
.bday-managed-tag-empty { margin: 0; color: var(--muted); font: .7rem/1.35 var(--sans); }
.bday-tag-add-form { display: flex; align-items: center; flex-wrap: wrap; gap: .35rem; width: 100%; }
.bday-tag-add-form[hidden] { display: none; }
.bday-tag-add-form label { color: var(--gold-ink); font: 600 .64rem/1.1 var(--sans); letter-spacing: .08em; text-transform: uppercase; }
.bday-tag-add-form input { flex: 1; min-width: 6rem; padding: .38rem .5rem; border: 1px solid var(--border); border-radius: var(--r-sm); background: rgba(255,255,255,.035); color: var(--text); font: .76rem var(--sans); }
.bday-tag-add-form button { min-height: 1.9rem; padding: .35rem .55rem; border: 1px solid var(--gold); border-radius: 999px; background: var(--gold-light); color: var(--gold); cursor: pointer; font: 600 .64rem/1.1 var(--sans); }
.bday-tag-add-form button:disabled { opacity: .42; cursor: not-allowed; }
.bday-tag-actions { display: flex; flex-wrap: wrap; gap: .35rem; }
.birth-tags { display: flex; flex-wrap: wrap; gap: .28rem; margin-top: .32rem; }
.birth-tag { padding: .25rem .42rem; color: var(--muted); border-color: var(--rule); }

.bday-list { display: flex; flex-direction: column; gap: .35rem; margin-bottom: .85rem; }
.birth-group-label { margin: .5rem .15rem .05rem; color: var(--muted); font: 600 .65rem/1.2 var(--sans); letter-spacing: .1em; text-transform: uppercase; }
.birth-empty { text-align: center; color: var(--muted); font-size: .85rem; padding: 1.5rem 0; }
.birth-item {
  position: relative;
  display: flex; align-items: center; gap: .35rem; padding: .22rem .35rem;
  border: 1px solid var(--rule); border-radius: var(--r-md);
  transition: border-color var(--ease), background var(--ease);
}
.birth-item:hover { border-color: var(--gold); background: rgba(199,154,84,.06); }
.birth-open { display: flex; flex: 1; align-items: center; gap: .7rem; min-width: 0; padding: .32rem; border: 0; border-radius: var(--r-sm); background: transparent; color: inherit; cursor: pointer; text-align: left; }
.birth-open:focus-visible { outline: 2px solid var(--gold); outline-offset: -2px; }
.birth-open:hover .birth-name { color: var(--gold-ink); }
.bi-chip {
  flex-shrink: 0;
  background: var(--card-paper);
}
.birth-item .bi-chip {
  min-inline-size: 2.35rem;
  block-size: 3.3rem;
  padding: .18rem .12rem;
  flex-direction: column;
  gap: .15rem;
  font-size: .82rem;
  line-height: 1;
}
.birth-item .bi-chip.bi-reciprocal { min-inline-size:1.7625rem; block-size:2.475rem; gap:.05rem; }
.birth-item .bi-reciprocal .bi-rank, .birth-item .bi-reciprocal .bi-suit { width:.8625rem; height:.8625rem; font-size:.75rem; }
.birth-item .bi-reciprocal .bi-suit .pip-svg { width:.75rem; height:.75rem; }
.birth-card-chips { display:flex; align-items:center; gap:.2rem; }
.birth-item .bi-rank { font-size: .9rem; }
.birth-item .bi-rank,
.birth-item .bi-suit {
  display: grid;
  place-items: center;
  width: 1.15rem;
  height: 1.15rem;
  font-size: 1rem;
}
.birth-item .bi-suit .pip-svg { width: 1rem; height: 1rem; }
.bi-chip.red { color: var(--red); }
.bi-chip-joker { background: var(--accent); color: var(--gold); font-size: .72em; }
.birth-item-body { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.birth-name { font-family: var(--sans); font-size: .94rem; font-weight: 600; color: var(--text); overflow-wrap: anywhere; }
.birth-date { font-family: var(--mono); font-size: .76rem; color: var(--muted); }
.birth-date-secondary { margin-top: .14rem; color: var(--text-muted); font-size: .74rem; }
.birth-favorite {
  display: grid; place-items: center; flex-shrink: 0;
  width: var(--tap-target); height: var(--tap-target);
  border: 0; border-radius: 50%; background: transparent; color: var(--muted); cursor: pointer;
  font: 1.05rem/1 var(--serif);
}
.birth-favorite:hover,
.birth-favorite.is-favorite { color: var(--gold); background: rgba(199,154,84,.1); }
.birth-favorite:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.birth-actions { position: relative; flex-shrink: 0; }
.birth-actions > summary {
  display: grid; place-items: center;
  width: var(--tap-target); height: var(--tap-target);
  border-radius: 50%; color: var(--muted); cursor: pointer;
  font: 700 1rem/.55 var(--sans); letter-spacing: .08em; list-style: none;
}
.birth-actions > summary::-webkit-details-marker { display: none; }
.birth-actions > summary:hover,
.birth-actions[open] > summary { color: var(--gold); background: rgba(199,154,84,.1); }
.birth-actions > summary:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.birth-actions-menu {
  position: absolute; z-index: 5; top: calc(100% - .25rem); right: 0;
  display: grid; min-width: 8.4rem; padding: .25rem;
  border: 1px solid var(--rule-strong); border-radius: var(--r-sm);
  background: var(--surface); box-shadow: var(--sh-md);
}
.birth-actions-menu button {
  min-height: 2rem; padding: .4rem .55rem; border: 0; border-radius: calc(var(--r-sm) - .15rem);
  background: transparent; color: var(--secondary); cursor: pointer; text-align: left;
  font: 600 .64rem/1 var(--sans); letter-spacing: .04em;
}
.birth-actions-menu button:hover { color: var(--gold); background: var(--gold-light); }
.birth-actions-menu [data-del] { color: #e98a8a; }
.birth-actions-menu [data-del]:hover { background: rgba(233,138,138,.12); color: #e98a8a; }
.bday-note { margin: .7rem 0 0; font-size: .68rem; color: var(--muted); text-align: center; }
.bday-pager { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: .65rem; margin: -.15rem 0 .8rem; }
.bday-page-btn {
  min-height: var(--tap-target);
  border: 1px solid var(--border); border-radius: 999px; padding: .3rem .65rem;
  background: transparent; color: var(--gold-ink); cursor: pointer; font: .64rem var(--sans);
}
.bday-page-btn:hover:not(:disabled) { border-color: var(--gold); background: rgba(199,154,84,.08); }
.bday-page-btn:disabled { opacity: .35; cursor: default; }
.bday-page-status { color: var(--muted); font: .66rem var(--mono); }

/* Keep keyboard focus explicit where the base input styles remove outlines. */
.finder-select:focus-visible,
.age-input:focus-visible,
.ba-field:focus-visible,
.bday-search input:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

@media (max-width: 560px) {
  .finder-day-input,
  .ba-field,
  .bday-search input { font-size: var(--text-base); }
  .finder-tools { margin-top: .9rem; }
  .it-row-wrap { margin-top: .7rem; }
  .birth-item { gap: var(--space-2); }
  .bday-io { flex-wrap: wrap; }
}

@media (max-width: 460px) {
  .bday-inline-head { align-items: flex-start; }
  .bday-heading { flex: 1 1 100%; justify-content: space-between; }
  .bday-head-actions { width: 100%; }
  .finder-persons {
    grid-template-columns: 1fr;
    justify-items: center;
  }
  .finder.rel-on .finder-persons {
    grid-template-columns: repeat(2, minmax(0, max-content));
    align-items: start;
    justify-content: center;
  }
  .finder-person {
    width: 100%;
  }
  .finder-inputs {
    position: relative;
    width: fit-content;
    max-width: 100%;
    margin: 0 auto;
    justify-content: center;
  }
  .finder-datepair {
    grid-template-columns: 2.65rem auto 2.65rem;
    min-width: 0;
    width: auto;
    padding: .28rem .35rem;
    border-radius: 14px;
  }
  .it-wheel-datepair {
    grid-template-columns: 2.65rem auto 2.65rem auto 4.2rem;
    width: max-content;
  }
  .finder-select-wrap {
    width: 2.65rem;
  }
  .it-wheel-year-wrap { width: 4.2rem; }
  .finder-datepair-slash {
    padding-top: .08rem;
    font-size: .9rem;
  }
  .finder-select {
    font-size: .94rem;
    padding: .38rem .42rem .42rem;
  }
  .finder-rel-toggle {
    margin-top: .2rem;
  }
  .finder-results {
    flex-direction: column;
    align-items: center;
  }
  .finder-results.triptych {
    display: grid;
    display: flex;
    flex-direction: row;
    align-items: flex-start;
    justify-content: center;
  }
}

/* ── Card Elements (added 2026-07-11) — four suits always
   shown at the foot of the page; selecting a suit reveals the A–K ranks
   + the planets rows and fills a reading panel. Modern | Olney voice
   toggle. Mirrors the I Ching trigram row. Logic: js/elements.js. */
.elements {
  padding: 0;
  margin-top: 0;
}
.el-inner { max-width: var(--max-w); margin: 0 auto; }
.el-voice { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.el-voice .astro-zodiac-tab { padding-left: .45rem; padding-right: .45rem; letter-spacing: .1em; }
.el-topline {
  min-height: 3rem;
}
.suit-row, .num-row {
  display: flex; flex-wrap: wrap; justify-content: center; align-items: center;
  gap: clamp(.6rem, 3vw, 1.7rem);
}
.suit-row { min-height: 3rem; }
@media (max-width: 700px) {
  .el-topline {
    min-height: 0;
  }
  .el-voice {
    position: static;
    transform: none;
  }
}
.num-row { gap: clamp(.35rem, 2vw, .85rem); margin-top: .9rem; }
.num-row[hidden] { display: none; }
.el-suit, .el-num {
  background: none; border: none; cursor: pointer; color: var(--gold);
  line-height: 1; padding: .15rem .35rem; border-radius: var(--r-sm);
  font-family: var(--serif);
  display: inline-flex; align-items: center; justify-content: center;
  min-width: var(--tap-target); min-height: var(--tap-target);
  transition: opacity var(--ease), transform var(--ease), text-shadow var(--ease);
}
.el-suit { font-size: clamp(1.9rem, 6vw, 2.7rem); opacity: 1; }
.el-suit .pip-svg { width: 1em; height: 1em; fill: currentColor; }
.el-num  { font-size: clamp(1rem, 3.4vw, 1.35rem); font-weight: 600; min-width: 1.5em; opacity: .55; }
.el-suit:hover, .el-suit:focus-visible { transform: translateY(-1px); text-shadow: 0 0 14px rgba(199,154,84,.5); }
.el-num:hover, .el-num:focus-visible { opacity: 1; }
.el-suit.sel, .el-num.sel { opacity: 1; transform: translateY(-2px); text-shadow: 0 0 16px rgba(199,154,84,.6); outline: 2px solid var(--gold); outline-offset: 2px; border-radius: 3px; }
.el-suit.lit, .el-num.lit { opacity: 1; text-shadow: 0 0 14px rgba(199,154,84,.7); }

.planet-row {
  display: flex; flex-wrap: wrap; justify-content: center; align-items: center;
  gap: clamp(.5rem, 2.6vw, 1.4rem);
  margin-top: clamp(1.3rem, 4vw, 2rem);
}
.planet-row[hidden] { display: none; }
.el-planet {
  background: none; border: none; cursor: pointer; color: var(--gold);
  font-family: var(--serif); line-height: 1; padding: .15rem .35rem;
  border-radius: var(--r-sm); font-size: clamp(1.5rem, 5vw, 2.1rem); opacity: .8;
  display: inline-flex; align-items: center; justify-content: center;
  min-width: var(--tap-target); min-height: var(--tap-target);
  transition: opacity var(--ease), transform var(--ease), text-shadow var(--ease);
}
.el-planet:hover, .el-planet:focus-visible { opacity: 1; transform: translateY(-1px); text-shadow: 0 0 14px rgba(199,154,84,.5); }
.el-planet.sel { opacity: 1; transform: translateY(-2px); text-shadow: 0 0 16px rgba(199,154,84,.6); outline: 2px solid var(--gold); outline-offset: 2px; border-radius: 3px; }

/* Historical Olney planet plate — the Elements section is the home for this
   source material, separate from the calculated natal chart. */
.el-olney-planets { max-width: 46rem; margin: 0 auto; color: var(--secondary); }
.el-olney-head { max-width: 38rem; margin: .8rem auto 1.5rem; text-align: center; }
.el-olney-book-title { margin-bottom: .35rem; color: var(--gold-ink); font: 600 .66rem/1.2 var(--sans); letter-spacing: .2em; text-transform: uppercase; }
.el-olney-source { display: inline-block; margin-bottom: .65rem; color: var(--gold); font: .62rem/1.3 var(--sans); letter-spacing: .08em; text-decoration: underline; text-underline-offset: .18em; }
.el-olney-source:hover, .el-olney-source:focus-visible { color: var(--text); }
.el-olney-source:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
.el-olney-title { color: var(--text); font-family: var(--serif); font-size: clamp(1.3rem, 4vw, 1.8rem); }
.el-olney-head p { margin: .7rem auto 0; color: var(--ink-muted); font: .9rem/1.6 var(--serif); }
.el-olney-list { display: grid; gap: .85rem; }
.el-olney-row { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr); gap: .85rem; align-items: center; text-align: left; }
.el-olney-glyph { display: grid; place-items: center; width: 4rem; height: 4rem; border: 1px solid var(--gold); border-radius: 50%; color: var(--gold-ink); font: 2rem/1 var(--serif); background: rgba(199,154,84,.07); }
.el-olney-name { display: flex; align-items: baseline; gap: .55rem; flex-wrap: wrap; }
.el-olney-copy h3 { margin: 0 0 .18rem; color: var(--gold-ink); font: 600 .7rem/1.2 var(--sans); letter-spacing: .12em; text-transform: uppercase; }
.el-olney-rule { color: var(--gold); font: 600 .6rem/1.2 var(--sans); letter-spacing: .1em; text-transform: uppercase; }
.el-olney-copy p { margin: 0; color: var(--secondary); font: .82rem/1.5 var(--serif); }
.el-olney-copy strong { color: var(--text); font-weight: 600; }
@media (max-width: 520px) {
  .el-olney-row { grid-template-columns: 3.3rem minmax(0, 1fr); gap: .55rem; }
  .el-olney-glyph { width: 3rem; height: 3rem; font-size: 1.5rem; }
  .el-olney-copy p { font-size: .78rem; }
}

.el-detailwrap { display: grid; grid-template-rows: 0fr; margin-top: 0; transition: grid-template-rows .4s var(--ease), margin-top .4s var(--ease); }
#elements.el-open .el-detailwrap { grid-template-rows: 1fr; margin-top: .9rem; }
.el-detailmin { overflow: hidden; }
.el-detail {
  display: flex; align-items: center; justify-content: center; gap: .4rem;
  max-width: 46rem; margin: 0 auto; padding: 0 .3rem;
  opacity: 0; transition: opacity .35s var(--ease);
}
#elements.el-open .el-detail { opacity: 1; }
.el-nav {
  flex: none; background: none; border: none; cursor: pointer; color: var(--gold-ink);
  font-size: 1.8rem; line-height: 1; padding: .2rem .5rem; border-radius: var(--r-sm);
  opacity: .6; transition: opacity var(--ease);
  min-width: var(--tap-target); min-height: var(--tap-target);
}
.el-nav:hover, .el-nav:focus-visible { opacity: 1; }
.el-card { flex: 1; min-width: 0; text-align: center; }
.el-head { display: flex; align-items: baseline; justify-content: center; gap: .55rem; margin-bottom: .5rem; }
.el-fig { font-family: var(--serif); font-size: 1.8rem; color: var(--gold); line-height: 1; }
.el-name { font-family: var(--serif); font-size: var(--text-lg); color: var(--text); }
.el-kws { display: flex; flex-wrap: wrap; justify-content: center; gap: .55rem; margin-bottom: .7rem; }
.el-text { color: var(--ink-muted); font-size: .96rem; line-height: 1.7; max-width: 42rem; margin: 0 auto; }
.el-text p { margin: 0 0 .7em; }
.el-keynote { margin-top: .6rem; font-family: var(--serif); font-style: italic; color: var(--gold-ink); }

.kw-tag {
  font-size: .67rem; font-weight: 600; letter-spacing: .07em;
  text-transform: uppercase; color: var(--gold-ink);
  background: transparent; padding: 0;
}

.pl-pop { max-width: 46rem; margin-inline: auto; }
.pl-detailwrap { display: grid; grid-template-rows: 0fr; margin-top: 0;
  transition: grid-template-rows .4s var(--ease), margin-top .4s var(--ease); }
.pl-pop.open .pl-detailwrap { grid-template-rows: 1fr; margin-top: .9rem; }
.pl-detailmin { overflow: hidden; }
.pl-detail { display: flex; align-items: center; justify-content: center; gap: .4rem;
  max-width: 46rem; margin: 0 auto; padding: 0 .3rem;
  opacity: 0; transform: translateY(-8px);
  transition: opacity .35s var(--ease), transform .35s var(--ease); }
.pl-pop.open .pl-detail { opacity: 1; transform: none; }
.pl-card { flex: 1; min-width: 0; text-align: center; background: transparent; border: none; padding: 0; }
.pl-head { display: flex; align-items: baseline; justify-content: center; gap: .55rem; margin-bottom: .5rem; }
.pl-fig { font-family: var(--serif); font-size: 1.8rem; color: var(--gold); line-height: 1; }
.pl-name { font-family: var(--serif); font-size: var(--text-lg); line-height: 1.1; color: var(--text); }
.pl-sub { font-family: var(--sans); font-size: .66rem; letter-spacing: .08em; text-transform: uppercase;
  color: var(--gold-ink); margin-bottom: .7rem; }
.pl-kws { display: flex; flex-wrap: wrap; justify-content: center; gap: .55rem; margin-bottom: .7rem; }
.pl-para { color: var(--ink-muted); font-size: .96rem; line-height: 1.7; max-width: 42rem; margin: 0 auto; }
.pl-para p { margin: 0 0 .7em; }
.pl-para p:last-child { margin-bottom: 0; }
.pl-attrs { display: block; max-width: 40rem; margin: 1.1rem auto 0;
  font-family: var(--sans); font-size: .82rem; }
.pl-attrs dt { color: var(--gold-ink); text-transform: uppercase; letter-spacing: .1em; font-size: .6rem;
  font-weight: 600; margin-top: .7rem; }
.pl-attrs dt:first-child { margin-top: 0; }
.pl-attrs dd { margin: .15rem 0 0; color: var(--secondary); }
.pl-syn { font-family: var(--serif); font-style: italic; font-size: 1.05rem; line-height: 1.6;
  color: var(--gold-ink); max-width: 40rem; margin: 1.1rem auto 0; }

@media (prefers-reduced-motion: reduce) {
  .el-detailwrap, .el-detail, .el-suit, .el-num, .el-planet, .pl-detailwrap, .pl-detail { transition: none; }
  html { scroll-behavior: auto; }
  .spread-card,
  .finder-tool-btn,
  .finder-modern-action-btn,
  .it-date-label,
  .it-reading-shift { transition: none; }
  .spread-card:hover,
  .finder-modern-action-btn:hover,
  .it-date-label:hover,
  .it-reading-shift:hover { transform: none; }
}

/* Nature Cards portable edition: two tools, with Cycles inline in Finder. */
.utility-dock { grid-template-columns: repeat(2, minmax(0, 1fr)); }
#fInTime > .ls-stat-label { text-align: center; }
button.ls-date-item {
  min-height: var(--tap-target);
  cursor: pointer;
  color: var(--secondary);
}
button.ls-date-item:hover {
