  background: linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.03)), rgba(17,12,33,.38);
  color: var(--secondary); cursor: pointer;
}
#finder .bday-settings-toggle svg,
#finder .q-settings-button svg {
