/* Calendar in Tools */
.tools-calendar { margin: .6rem 0 1rem; text-align: left; }
.tools-calendar[hidden] { display: none; }
.tools-calendar-header { display: flex; justify-content: space-between; align-items: end; gap: .5rem; margin-bottom: 1rem; }
.tools-calendar-label { color: var(--gold-ink); font-size: .65rem; letter-spacing: .12em; text-transform: uppercase; }
.tools-calendar-header h4 { margin: .25rem 0 0; color: #eee; font: 400 1.3rem/1.2 var(--serif); }
.tools-calendar-nav { display: flex; gap: .3rem; }
.tools-calendar-nav button { min-height: 2.2rem; padding: 0 .65rem; border: 1px solid #49443c; border-radius: .5rem; background: #20201e; color: #eee; cursor: pointer; }
.tools-calendar-week, .tools-calendar-days { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: .25rem; }
.tools-calendar-days { grid-template-rows: repeat(6, 3.3rem); }
.tools-calendar-week { margin-bottom: .4rem; text-align: center; color: #aaa; font-size: .62rem; text-transform: uppercase; }
.tools-calendar-day { position: relative; min-width: 0; min-height: 3.3rem; padding: .3rem .35rem; display: flex; flex-direction: column; align-items: stretch; border: 1px solid #e5e2dc; border-radius: .45rem; background: #fff; color: #555; text-align: left; font: 600 .68rem/1 var(--sans); font-variant-numeric: tabular-nums; cursor: pointer; }
.tools-calendar-day:hover, .tools-calendar-day.is-selected { border-color: var(--gold); }
.tools-calendar-day.is-selected { box-shadow: inset 0 0 0 2px #9b6a22; }
.tools-calendar-day.is-today { border: 2px solid #9b6a22; background: #fff5d9; }
.tools-calendar-day.is-today::after { content: 'TODAY'; position: absolute; right: .2rem; top: .22rem; padding: .12rem .2rem; border-radius: .2rem; background: #80571f; color: #fff; font: 700 .44rem/1 var(--sans); letter-spacing: .02em; }
.tools-calendar-card { flex: 1; display: flex; align-items: center; justify-content: center; color: #171717; font: 600 1.1rem/1 var(--serif); }
.tools-calendar-card.is-red { color: #a52b2b; }
.tools-calendar-hint { margin: .8rem 0 0; color: #aaa; font-size: .7rem; }
.tools-calendar-hint span { color: var(--gold); font-size: .5rem; vertical-align: middle; }
@media (max-width: 380px) { .tools-calendar-days { grid-template-rows: repeat(6, 3rem); } .tools-calendar-day { min-height: 3rem; padding: .25rem; } .tools-calendar-card { font-size: .95rem; } }

.tools-calendar-layout { display: grid; grid-template-columns: minmax(0, 1fr) 4.7rem; gap: .55rem; }
.tools-calendar-weekly-heading { height: 1.1rem; margin-bottom: .4rem; color: var(--gold-ink); text-align: center; font-size: .62rem; text-transform: uppercase; }
.tools-calendar-weekly-list { display: grid; grid-template-rows: repeat(6, 3.3rem); gap: .25rem; }
.tools-calendar-weekly-entry { display: flex; flex-direction: column; justify-content: center; align-items: center; gap: .2rem; border: 1px solid #484035; border-radius: .45rem; background: #1d1b18; }
.tools-calendar-weekly-range { color: #c7bba7; font: .57rem/1 var(--sans); white-space: nowrap; }
.tools-calendar-weekly-card { color: #eee; font: 600 1rem/1 var(--serif); }
.tools-calendar-weekly-card.is-red { color: #e89988; }
@media (max-width: 380px) { .tools-calendar-layout { grid-template-columns: minmax(0, 1fr) 4.15rem; gap: .3rem; } .tools-calendar-weekly-list { grid-template-rows: repeat(6, 3rem); } .tools-calendar-weekly-range { font-size: .5rem; } }

.tools-calendar-weekly-entry.is-current { border: 2px solid #ddbb78; background: #45341e; box-shadow: 0 0 0 1px #ddbb7840; gap: .12rem; }
.tools-calendar-current-label { color: #f2d9a2; font: 700 .5rem/1 var(--sans); text-transform: uppercase; letter-spacing: .04em; }
.tools-calendar-weekly-entry.is-current .tools-calendar-weekly-range { color: #f0e2ca; }
.tools-calendar-weekly-entry.is-current .tools-calendar-weekly-card { color: #fff; }
.tools-calendar-weekly-entry.is-current .tools-calendar-weekly-card.is-red { color: #ffb6a8; }

.tools-calendar-datepair { grid-template-columns: 3.2rem auto 4rem; margin-top: .25rem; }
.tools-calendar-datepair .tools-calendar-year-wrap { width: 4rem; }
@media (max-width: 380px) { .tools-calendar-datepair { grid-template-columns: 2.5rem auto 3.4rem; padding: .2rem; } .tools-calendar-datepair .finder-select-wrap { width: auto; } .tools-calendar-datepair .finder-select { padding-inline: .15rem; } .tools-calendar-nav button { padding-inline: .45rem; } }

.tools-calendar-date-nav { align-items: center; margin-top: .25rem; }
.tools-calendar-date-nav .tools-calendar-datepair { margin-top: 0; }
.tools-calendar-actions { flex-wrap: wrap; justify-content: flex-end; }
.tools-calendar-layout[hidden], .tools-calendar-year-view[hidden] { display: none; }
.tools-calendar-year-view { max-height: min(65vh, 36rem); overflow-y: auto; padding-right: .3rem; }
.tools-calendar-year-month { margin: 0 0 1.1rem; }
.tools-calendar-year-month h4 { margin: 0 0 .5rem; color: var(--gold-ink); font: 500 1rem/1.2 var(--serif); }
@media (max-width: 380px) { .tools-calendar-header { align-items: flex-start; flex-wrap: wrap; } }

/* Full-year grid: months across, days down. */
.tools-calendar-year-view { overflow: auto; padding: 0; }
.tools-calendar-year-grid { border-collapse: separate; border-spacing: 2px; width: 100%; min-width: 34rem; table-layout: fixed; }
.tools-calendar-year-grid th { color: #ddbb78; font: 600 .65rem/1 var(--sans); text-align: center; padding: .3rem .1rem; background: #0c0c0c; }
.tools-calendar-year-grid thead th { position: sticky; top: 0; z-index: 2; }
.tools-calendar-year-grid th:first-child { position: sticky; left: 0; z-index: 1; width: 2rem; }
.tools-calendar-year-grid thead th:first-child { z-index: 3; }
.tools-calendar-year-grid td { padding: 0; height: 2rem; }
.tools-calendar-year-grid td.is-empty { background: #1b1b1b; border-radius: .25rem; }
.tools-calendar-year-day { width: 100%; height: 2rem; border: 1px solid #e5e2dc; border-radius: .25rem; background: #fff; color: #171717; font: 600 .8rem/1 var(--serif); cursor: pointer; }
.tools-calendar-year-day.is-red { color: #a52b2b; }
.tools-calendar-year-day.is-today { background: #fff5d9; border: 2px solid #9b6a22; }
.tools-calendar-year-day.is-selected { box-shadow: inset 0 0 0 2px #9b6a22; }

/* Use the same suit artwork as the rest of the app. */
.tools-calendar-card, .tools-calendar-weekly-card, .tools-calendar-year-day { display: inline-flex; align-items: center; justify-content: center; gap: .05em; }
.tools-calendar-card .pip-svg, .tools-calendar-weekly-card .pip-svg, .tools-calendar-year-day .pip-svg { display: inline-block; flex: none; width: .95em; height: .95em; }
.tools-calendar-card.is-red, .tools-calendar-year-day.is-red { color: var(--red); }

/* Keep all twelve months visible together on narrow screens. */
@media (max-width: 600px) {
  .tools-calendar-year-grid { min-width: 0; border-spacing: 1px; }
  .tools-calendar-year-grid th { padding: .3rem 0; font-size: .55rem; }
  .tools-calendar-year-grid th:first-child { width: 1.35rem; }
  .tools-calendar-year-grid tbody th { padding: 0; }
  .tools-calendar-year-grid td { height: .7rem; line-height: 0; vertical-align: middle; }
  .tools-calendar-year-day { height: .7rem; min-width: 0; padding: 0; gap: 0; font-size: clamp(.43rem, 1.9vw, .6rem); border-radius: .18rem; }
  .tools-calendar-year-day .pip-svg { width: .8em; height: .8em; }
}

@media (max-width: 600px) {
  #ncOrderControls:has(.tools-calendar-year-view:not([hidden])) .tools-calendar-header { margin-bottom: .35rem; }
  #ncOrderControls:has(.tools-calendar-year-view:not([hidden])) .tools-calendar-label { display: none; }
  #ncOrderControls:has(.tools-calendar-year-view:not([hidden])) .tools-calendar-hint { display: none; }
  #ncOrderControls:has(.tools-calendar-year-view:not([hidden])) .tools-calendar-year-view { max-height: none; overflow: visible; }
  #ncOrderControls:has(.tools-calendar-year-view:not([hidden])) .tools-calendar-year-grid { border-spacing: 1px 0; }
}

/* Gematria calculator */
.tools-gematria { margin: .75rem 0 1rem; text-align: left; }
.tools-gematria[hidden] { display: none; }
.gematria-label { display: block; margin-bottom: .45rem; color: var(--gold-ink); font: 600 .7rem/1.3 var(--sans); letter-spacing: .08em; text-transform: uppercase; }
.tools-gematria textarea { display: block; width: 100%; box-sizing: border-box; resize: vertical; min-height: 4.5rem; padding: .75rem; border: 1px solid #49443c; border-radius: .6rem; background: #171717; color: #eee; font: 1rem/1.45 var(--sans); }
.gematria-help, .gematria-empty { color: #aaa; font-size: .78rem; line-height: 1.5; }
.gematria-help { margin: .55rem 0 1rem; }
.gematria-empty { margin: 1.5rem 0; text-align: center; }
.gematria-total { color: #ddd; font-size: .85rem; text-align: center; }
.gematria-card-button { display: flex; flex-direction: column; align-items: center; gap: .5rem; margin: .8rem auto; padding: 0; border: 0; background: transparent; color: #eee; cursor: pointer; }
