.gematria-card-name { font: 400 1.1rem/1.3 var(--serif); text-transform: capitalize; }
.gematria-card-action { color: var(--gold-ink); font-size: .75rem; }
.gematria-breakdown { border-top: 1px solid #343434; padding-top: .65rem; color: #ccc; font-size: .78rem; }
.gematria-breakdown summary { color: var(--gold-ink); cursor: pointer; }
.gematria-breakdown p { overflow-wrap: anywhere; line-height: 1.8; }

/* Keep all dates in view in the full-year calendar at every width. */
.tools-calendar-year-view { max-height: none; overflow: visible; }
.tools-calendar-year-grid { min-width: 0; border-spacing: 1px 0; }
.tools-calendar-year-grid th { padding: .2rem 0; font-size: clamp(.5rem, 1.5vw, .65rem); }
.tools-calendar-year-grid th:first-child { width: 1.35rem; }
.tools-calendar-year-grid tbody th { padding: 0; }
.tools-calendar-year-grid td { height: clamp(.55rem, calc((100dvh - 26rem) / 31), .9rem); line-height: 0; vertical-align: middle; }
.tools-calendar-year-day { height: clamp(.55rem, calc((100dvh - 26rem) / 31), .9rem); min-width: 0; padding: 0; gap: 0; font-size: clamp(.43rem, 1.9vw, .65rem); border-radius: .18rem; }
.tools-calendar-year-day .pip-svg { width: .8em; height: .8em; }
#ncOrderControls:has(.tools-calendar-year-view:not([hidden])) .tools-calendar-header { margin-bottom: .35rem; }
#ncOrderControls:has(.tools-calendar-year-view:not([hidden])) .tools-calendar-hint { display: none; }

.site-title-refresh { padding: .4rem .2rem; margin: -.4rem -.2rem; border: 0; border-radius: .25rem; background: transparent; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; cursor: pointer; }
