/* Alternate paired month columns in the Sun–Earth view. */
.tools-calendar-year-grid.is-paired tr > :is(:nth-child(4), :nth-child(5), :nth-child(8), :nth-child(9), :nth-child(12), :nth-child(13)) > .tools-calendar-year-day:not(.is-today) { background: #e9e5dc; border-color: #ded8cc; }
.tools-calendar-year-grid.is-paired thead tr > :is(:nth-child(4), :nth-child(5), :nth-child(8), :nth-child(9), :nth-child(12), :nth-child(13)) { background: #28251f; }
.tools-calendar-year-grid.is-paired td.is-empty:is(:nth-child(4), :nth-child(5), :nth-child(8), :nth-child(9), :nth-child(12), :nth-child(13)) { background: #292720; }

.tools-calendar-year-day.is-exception { position: relative; }
